function V(x, y1, y2, t, name) { ROADS.push({ h: false, x, y1, y2, T: RT[t], name }); }

function riverCX(y) { return 5450 + Math.sin(y * 0.00105) * 140 + Math.sin(y * 0.0029 + 1.3) * 45; }
function riverHW(y) { return 135 + Math.sin(y * 0.0021 + 0.5) * 22; }

