  if (o.lastLot) { const r = F.rect(W - 4, 5, W, D); addWall(r[0], r[1], r[2], r[3], wallCol); }
  if (o.back) { const r = F.rect(4, D - 4, W, D); addWall(r[0], r[1], r[2], r[3], wallCol); }
