  const wallCol = '#d8cfb8';
  { const r = F.rect(0, 0, 4, F.D); addWall(r[0], r[1], r[2], r[3], wallCol); }
  { const r = F.rect(4, F.D - 4, F.W, F.D); addWall(r[0], r[1], r[2], r[3], wallCol); }
  const g = F.rect(12, 16, 112, 118);
