/* ---------- pontos de interesse e percursos ---------- */
// tira árvores que acabaram em cima do asfalto (ruas alargadas depois do plantio)
/* RUAS 10% MAIS LARGAS (nov/2026): a cidade inteira é montada com as medidas antigas (os sorteios, lotes, lojas e postes
   não mudam) e só depois o asfalto cresce 10% para dentro da calçada ou do acostamento: a beira de fora fica no mesmo lugar.
   O desenho das ruas é feito na hora de mostrar (bake guarda a função), então já sai com a largura nova. */
const RUA_LARG = 1.1;
function alargaRuas() {
  const old = {};
  for (const k in RT) {
    if (RT[k].larga) continue; // rua e avenida da cidade já são montadas largas
    const T = RT[k], dw = T.w * (RUA_LARG - 1) / 2; old[k] = T.w / 2;
    T.w = +(T.w * RUA_LARG).toFixed(2);
    if (T.sw) T.sw = +(T.sw - dw).toFixed(2); else if (T.shoulder) T.shoulder = +Math.max(5, T.shoulder - dw).toFixed(2);
    T.lanes = T.lanes.map((l) => +(l * RUA_LARG).toFixed(2));
    if (T.laneDiv) T.laneDiv = +(T.laneDiv * RUA_LARG).toFixed(2);
  }
  const marca = (x, y, tipo, ponte) => {
    const gx = Math.floor(x / GC), gy = Math.floor(y / GC);
    if (gx < 0 || gy < 0 || gx >= GW || gy >= GH) return;
    const i = gy * GW + gx, g = ground[i];
    if (g === SF.WATER) { if (ponte) ground[i] = SF.BRIDGE; return; }
    if (g === SF.BRIDGE || g === SF.ROAD) return;
    ground[i] = tipo;
  };
  for (const e of World.edges) {
    const h0 = e.hw0 = e.hw, h1 = e.hw = e.T.w / 2, tipo = e.T.asphalt ? SF.ROAD : SF.DIRT;
    // a faixa nova entre a beira antiga e a nova vira pista (só as casinhas da grade cujo centro cai dentro do asfalto novo)
    const x0 = Math.min(e.a.x, e.b.x) - h1, x1 = Math.max(e.a.x, e.b.x) + h1, y0 = Math.min(e.a.y, e.b.y) - h1, y1 = Math.max(e.a.y, e.b.y) + h1;
    for (let gy = Math.floor(y0 / GC); gy <= Math.floor(y1 / GC); gy++) for (let gx = Math.floor(x0 / GC); gx <= Math.floor(x1 / GC); gx++) {
      const cx = gx * GC + 5, cy = gy * GC + 5;
      const d = e.h ? Math.abs(cy - e.a.y) : Math.abs(cx - e.a.x), along = e.h ? cx : cy, a0 = e.h ? Math.min(e.a.x, e.b.x) : Math.min(e.a.y, e.b.y), a1 = e.h ? Math.max(e.a.x, e.b.x) : Math.max(e.a.y, e.b.y);
      if (d >= h0 - 3 && d < h1 && along >= a0 && along <= a1) marca(cx, cy, tipo, e.bridge && cx > e.bridge.x0 && cx < e.bridge.x1);
    }
    if (e.bridge && e.bridge.rails) {
      const d = h1 - h0, [r1, r2] = e.bridge.rails;
      r1.y0 -= d; r1.y1 -= d; r2.y0 += d; r2.y1 += d;
      colGrid.insert(r1, r1.x0, r1.y0, r1.x1, r1.y1); colGrid.insert(r2, r2.x0, r2.y0, r2.x1, r2.y1);
    }
  }
  // faixa de pedestre e linha de parada começam na beira nova do cruzamento
  const perpN = (e, n) => { let m = 0; for (const o of n.edges) if (o.h !== e.h) m = Math.max(m, o.hw); return m; };
  for (const e of World.edges) { e.perpA = perpN(e, e.a); e.perpB = perpN(e, e.b); }
  for (const n of World.nodes) {
    let hv = 0, hh = 0, asph = false;
    for (const e of n.edges) { if (e.h) hh = Math.max(hh, e.hw); else hv = Math.max(hv, e.hw); if (e.T.asphalt) asph = true; }
    if (!hv) hv = hh; if (!hh) hh = hv;
    n.hx0 = n.hx; n.hy0 = n.hy; n.hx = hv; n.hy = hh;
    for (let gy = Math.floor((n.y - hh) / GC); gy <= Math.floor((n.y + hh) / GC); gy++) for (let gx = Math.floor((n.x - hv) / GC); gx <= Math.floor((n.x + hv) / GC); gx++) {
      const cx = gx * GC + 5, cy = gy * GC + 5;
      if (Math.abs(cx - n.x) < hv && Math.abs(cy - n.y) < hh) marca(cx, cy, asph ? SF.ROAD : SF.DIRT, false);
    }
  }
}
// depois de alargar: semáforo, poste, radar ou objeto de calçada que ficou com o pé no asfalto novo vai para a beira
function empurraDaPista() {
  const faixas = World.edges; // todas: as alargadas depois e as que já nascem largas (rua e avenida da cidade)
  const desloca = (x, y, r) => {
    for (const e of faixas) {
      const al = e.h ? x : y, a0 = e.h ? Math.min(e.a.x, e.b.x) : Math.min(e.a.y, e.b.y), a1 = e.h ? Math.max(e.a.x, e.b.x) : Math.max(e.a.y, e.b.y);
      if (al < a0 - r || al > a1 + r) continue;
      const d = (e.h ? y - e.a.y : x - e.a.x);
      const fundo = e.hw0 && e.hw0 < e.hw ? e.hw0 - r - 1 : e.hw - 14; // mais para dentro que isso é de propósito (obra, cone, lombada)
      if (Math.abs(d) >= e.hw + r || Math.abs(d) < fundo) continue;
      const v = (d < 0 ? -1 : 1) * (e.hw + r + 1) - d;
      return e.h ? [0, v] : [v, 0];
    }
    for (const n of World.nodes) {
      const dx = x - n.x, dy = y - n.y, ox = n.hx0 || n.hx, oy = n.hy0 || n.hy;
      if (Math.abs(dx) >= n.hx + r || Math.abs(dy) >= n.hy + r) continue;
      if (Math.abs(dx) < ox - r - 1 && Math.abs(dy) < oy - r - 1) continue;
      const vx = (dx < 0 ? -1 : 1) * (n.hx + r + 1) - dx, vy = (dy < 0 ? -1 : 1) * (n.hy + r + 1) - dy;
      return Math.abs(vx) < Math.abs(vy) ? [vx, 0] : [0, vy];
    }
    return null;
  };
  // repete até sair de todas as pistas (no canto, sai da rua e do cruzamento)
  const deslocaTudo = (x, y, r) => {
    let tx = 0, ty = 0;
    for (let i = 0; i < 4; i++) { const d = desloca(x + tx, y + ty, r); if (!d) break; tx += d[0]; ty += d[1]; }
    return tx || ty ? [tx, ty] : null;
  };
  const q = [], movidos = new Set();
  const moveCol = (c, d) => {
    if (c.t === 0) { c.x0 += d[0]; c.x1 += d[0]; c.y0 += d[1]; c.y1 += d[1]; colGrid.insert(c, c.x0, c.y0, c.x1, c.y1); }
    else { c.x += d[0]; c.y += d[1]; colGrid.insert(c, c.x - c.r, c.y - c.r, c.x + c.r, c.y + c.r); }
    movidos.add(c);
  };
  let n = 0;
  for (const t of World.tall) {
    if (t.x === undefined || t.x0 !== undefined || t.removed) continue;
    const r = t.kind === 'tree' ? 6 : t.kind === 'lamp' ? 4 : 5, d = deslocaTudo(t.x, t.y, r);
    if (!d) continue;
    const ox = t.x, oy = t.y, hx = t.hx, hy = t.hy;
    colGrid.query(ox - 6, oy - 6, ox + 6, oy + 6, q);
    for (const c of q.slice()) if (!movidos.has(c) && c.tag !== 'rail' && (c.t === 1 ? Math.hypot(c.x - ox, c.y - oy) < 3 : Math.abs((c.x0 + c.x1) / 2 - ox) < 3 && Math.abs((c.y0 + c.y1) / 2 - oy) < 3)) moveCol(c, d);
    lightGrid.query(ox - 80, oy - 80, ox + 80, oy + 80, q);
    for (const L of q.slice()) if (Math.hypot(L.x - ox, L.y - oy) < 3 || (hx !== undefined && Math.hypot(L.x - hx, L.y - hy) < 3)) { L.x += d[0]; L.y += d[1]; lightGrid.insert(L, L.x - L.r, L.y - L.r, L.x + L.r, L.y + L.r); }
    t.x += d[0]; t.y += d[1]; if (hx !== undefined) { t.hx += d[0]; t.hy += d[1]; }
    if (t.col && !movidos.has(t.col) && t.col.t === 1) moveCol(t.col, d);
    rendGrid.insert(t, t.x - 90, t.y - 90, t.x + 90, t.y + 90);
    n++;
  }
  // objetos baixos com colisão (mesinha, banco, ponto de ônibus…): move a colisão e o desenho juntos
  const vistos = new Set();
  for (const cell of colGrid.cells) if (cell) for (const c of cell) {
    if (vistos.has(c) || movidos.has(c)) continue; vistos.add(c);
    if (c.tag === 'rail' || c.tag === 'none' || c.tag === 'event') continue;
    const w = c.t === 0 ? c.x1 - c.x0 : c.r * 2, h = c.t === 0 ? c.y1 - c.y0 : c.r * 2;
    if (w > 40 || h > 40) continue;
    const cx = c.t === 0 ? (c.x0 + c.x1) / 2 : c.x, cy = c.t === 0 ? (c.y0 + c.y1) / 2 : c.y;
    const d = deslocaTudo(cx, cy, Math.max(w, h) / 2); if (!d) continue;
    moveCol(c, d);
    const o = c.brk && c.brk.obj; if (o && o.x !== undefined && o.x0 === undefined) { o.x += d[0]; o.y += d[1]; o._mov = 1; }
    n++;
  }
  // áreas onde pedestres e bichos andam: recorta o pedaço que virou pista (alargamento depois de montar)
  for (const D of World.animalsDef || []) {
    const R = D.rect; if (!R) continue;
    for (const e of World.edges) {
      if (!(e.hw0 && e.hw > e.hw0)) continue;
      const al0 = e.h ? Math.min(e.a.x, e.b.x) : Math.min(e.a.y, e.b.y), al1 = e.h ? Math.max(e.a.x, e.b.x) : Math.max(e.a.y, e.b.y);
      if ((e.h ? R[2] : R[3]) < al0 || (e.h ? R[0] : R[1]) > al1) continue;
      const c = e.h ? e.a.y : e.a.x, lo = c - e.hw - 4, hi = c + e.hw + 4, i0 = e.h ? 1 : 0, i1 = e.h ? 3 : 2;
      if (R[i1] <= lo || R[i0] >= hi) continue;
      if (R[i0] < lo && R[i1] > lo && R[i1] < hi) R[i1] = lo; // a área encosta por cima/esquerda
      else if (R[i1] > hi && R[i0] < hi && R[i0] > lo) R[i0] = hi; // por baixo/direita
    }
  }
  // objetos baixos sem colisão própria (ou cuja colisão não aponta para eles)
  for (const p of World.props || []) {
    if (p._mov) continue;
    const ox = p.x, oy = p.y, d = deslocaTudo(ox, oy, Math.max(p.w || 0, p.h || 0, 10) / 2); if (!d) continue;
    p.x += d[0]; p.y += d[1]; p._mov = 1;
    colGrid.query(ox - 6, oy - 6, ox + 6, oy + 6, q);
    for (const c of q.slice()) if (!movidos.has(c) && (c.t === 1 ? Math.hypot(c.x - ox, c.y - oy) < 3 : Math.abs((c.x0 + c.x1) / 2 - ox) < 3 && Math.abs((c.y0 + c.y1) / 2 - oy) < 3)) moveCol(c, d);
    n++;
  }
  return n;
}
function pruneRoadTrees() {
  let n = 0;
  for (const t of World.tall) {
    if (t.kind !== 'tree' || t.removed) continue;
    const gt = groundAt(t.x, t.y);
    let onRoad = gt === SF.ROAD || gt === SF.BRIDGE || gt === SF.DIRT;
    if (!onRoad) { const ne = nearestEdge(t.x, t.y); if (ne && ne.d !== undefined && ne.d < ne.e.hw + 4) onRoad = true; }
    if (onRoad) { t.removed = true; if (t.col) { t.col.x = t.col.y = -1e6; t.col.r = 0; t.col.tag = 'none'; t.col.brk = null; } n++; }
  }
  World.tall = World.tall.filter((t) => !t.removed);
  return n;
}
// tira 20% das árvores do jogo (escolhidas pela posição, sem sorteio: o resto do mapa não muda)
function thinTrees() {
  let n = 0;
  for (const t of World.tall) if (t.kind === 'tree' && !t.removed && hash2((t.x * 7) | 0, (t.y * 3) | 0) < 0.2) {
    t.removed = true; n++;
    if (t.col) { t.col.x = t.col.y = -1e6; t.col.r = 0; t.col.tag = 'none'; t.col.brk = null; }
  }
  World.tall = World.tall.filter((t) => !t.removed);
  // tira as árvores removidas da lista de desenho (nem entram na conta do quadro)
  for (let i = 0; i < rendGrid.cells.length; i++) { const a = rendGrid.cells[i]; if (a && a.some((o) => o.removed)) rendGrid.cells[i] = a.filter((o) => !o.removed); }
  return n;
}
// buracos soltos no asfalto: 20% das ruas da cidade e 30% das ruas da favela (sorteio próprio: não mexe no mapa)
const BURACO_FAVELA = { saopedro: 1, terravermelha: 1, feurosa: 1, carapina: 1 };
function addBuracos() {
  const R = mulberry32(5150), longeDe = (x, y, L, d) => L.every((q) => Math.abs(q.x - x) > d || Math.abs(q.y - y) > d);
  for (const e of World.edges) {
    if (!e.T.asphalt || e.bridge || e.len < 260) continue;
    const mx = e.h ? (e.a.x + e.b.x) / 2 : e.a.x, my = e.h ? e.a.y : (e.a.y + e.b.y) / 2, rk = regionKeyAt(mx, my), G = REGIONS[rk];
    const fav = BURACO_FAVELA[rk], cid = !fav && G && G.city >= 0.45 && G.rural < 0.5;
    const sorte = R(), n = 1 + (R() < 0.35 ? 1 : 0);
    if (!(fav ? sorte < 0.3 : cid ? sorte < 0.2 : false)) continue;
    const nx = e.h ? 0 : 1, ny = e.h ? 1 : 0;
    for (let i = 0; i < n; i++) {
      const s = (e.clearA || 40) + 50 + R() * Math.max(1, e.len - (e.clearA || 40) - (e.clearB || 40) - 100);
      const lane = e.T.lanes[Math.floor(R() * e.T.lanes.length)], sd = R() < 0.5 ? 1 : -1;
      const x = e.a.x + e.dx * s + nx * lane * sd + (R() - 0.5) * 8, y = e.a.y + e.dy * s + ny * lane * sd + (R() - 0.5) * 8;
      if (!longeDe(x, y, World.buracos, 90) || !longeDe(x, y, World.obras, 120)) continue;
      if (World.bumps.some((b) => x > b.x0 - 40 && x < b.x1 + 40 && y > b.y0 - 40 && y < b.y1 + 40)) continue;
      const g = groundAt(x, y); if (g !== SF.ROAD && g !== SF.PAVED) continue;
      const k = 0.7 + R() * 0.45, a = R() * 3, p = { type: 'buraco', x, y, k, a };
      bake(x - 16, y - 16, x + 16, y + 16, 5.6, (gc) => drawBuraco(gc, p));
      World.buracos.push({ x, y, r: 9 * k, t: -9 });
    }
  }
}
function drawBuraco(g, p) {
  g.save(); g.translate(p.x, p.y); g.rotate(p.a); g.scale(p.k, p.k);
  g.fillStyle = 'rgba(40,38,36,0.55)'; g.beginPath(); g.ellipse(0, 0, 13, 9, 0, 0, TAU); g.fill(); // asfalto rachado em volta
  g.fillStyle = '#121214'; g.beginPath(); g.ellipse(0, 0, 9, 6, 0, 0, TAU); g.fill();
  g.strokeStyle = 'rgba(110,104,92,0.55)'; g.lineWidth = 1; g.stroke();
  g.strokeStyle = 'rgba(20,20,22,0.7)'; g.beginPath(); g.moveTo(8, 2); g.lineTo(14, 4); g.moveTo(-8, -3); g.lineTo(-13, -6); g.stroke();
  g.restore();
}
function markReflections() {
  for (const L of World.lights) {
    for (let dy = 30; dy <= 260; dy += 20) if (groundAt(L.x, L.y + dy) === SF.WATER) { L.refl = dy + 30; break; }
  }
}
function addFlags(x1, y1, x2, y2, bulbs) {
  if (regionKeyAt((x1 + x2) / 2, (y1 + y2) / 2) === 'fazenda') { rnd(); return; } // na fazenda não tem bandeirinha (o sorteio do mapa avança igual)
  const f = { kind: 'flags', x1, y1, x2, y2, h: 44, bulbs: !!bulbs, x: (x1 + x2) / 2, y: (y1 + y2) / 2, seed: rnd() };
  addTall(f, Math.min(x1, x2) - 20, Math.min(y1, y2) - 30, Math.max(x1, x2) + 20, Math.max(y1, y2) + 20);
}
function addGrill(x, y) {
  if (areaBlocked(x - 8, y - 6, x + 8, y + 6)) return;
  const g = { kind: 'grill', x, y, h: 10 };
  addTall(g, x - 30, y - 30, x + 30, y + 30); addCircCol(x, y, 6, 'prop').brk = { kind: 'tall', obj: g };
  World.grills.push(g);
  addLight(x, y, 70, 0.7, 'sodium');
  World.animalsDef.push({ type: 'person', n: 3, rect: [x - 30, y - 8, x + 30, y + 8], look: { dance: true } });
}
function buildFesta() {
  for (const s of World.shops) {
    if (!['bar', 'lanchonete', 'churrascaria', 'mercado'].includes(s.kind)) continue;
    const ne = nearestEdge(s.x, s.y), e = ne.e;
    const sd = e.h ? Math.sign((s.bld ? s.bld.cy : s.y) - e.a.y) || 1 : Math.sign((s.bld ? s.bld.cx : s.x) - e.a.x) || 1;
    const o = e.hw + (e.T.sw ? e.T.sw * 0.5 : 14);
    if (e.h) addGrill(s.x + 70, e.a.y + sd * o); else addGrill(e.a.x + sd * o, s.y + 70);
  }
  { const R = cellRect(2, 1); addGrill(R.x1 - 80, R.y1 - 26); }
  { const R = cellRect(0, 5); addGrill(XS[1] - RT.street.w / 2 - 11, (R.y0 + R.y1) / 2 + 60); }
  addGrill(1640, 5900);
  // bandeirinhas de festa junina e gambiarras de luz perto dos comércios do bairro
  for (const s of World.shops) {
    if (!['bar', 'lanchonete', 'padaria', 'mercado', 'moquecaria', 'churrascaria'].includes(s.kind)) continue;
    const ne = nearestEdge(s.x, s.y), e = ne.e;
    const span = e.hw + (e.T.sw || 8) + 2;
    for (const d of [-70, -35, 0, 35, 70]) {
      const zig = (d / 35) % 2 ? 14 : -14;
      if (e.h) addFlags(s.x + d, e.a.y - span, s.x + d + zig, e.a.y + span, s.kind === 'bar' || s.kind === 'lanchonete');
      else addFlags(e.a.x - span, s.y + d, e.a.x + span, s.y + d + zig, s.kind === 'bar' || s.kind === 'lanchonete');
    }
  }
  // arraial na praça, no campo de várzea, no sítio e na fazenda
  const lines = [[1530, 1180, 1980, 1380], [1530, 1380, 1980, 1180], [380, 3380, 770, 3760], [380, 3760, 770, 3380], [7860, 1150, 8140, 1270], [7860, 1270, 8140, 1150], [7960, 4500, 8220, 4620], [7960, 4620, 8220, 4500]];
  for (const [a, b, c, d] of lines) addFlags(a, b, c, d, true);
}
