    World.rachas.push({ id, name, rival, bet, start: pts[0], pts: pts.slice(1), all: pts, len, rivalTime: len / rt, a0: Math.atan2(pts[1][1] - pts[0][1], pts[1][0] - pts[0][0]), racha: true });
