        g.save(); g.translate(mx, my); if (!e.h) g.rotate(Math.PI / 2);
        g.lineWidth = 3 * k; g.strokeStyle = 'rgba(5,7,11,0.85)'; g.strokeText(e.name.toUpperCase(), 0, 0); g.fillStyle = '#e9edf5'; g.fillText(e.name.toUpperCase(), 0, 0);
