  g.strokeStyle = '#2a2a2a'; g.lineWidth = 2; g.beginPath(); g.arc(-12, -18, 8, 0, TAU); g.moveTo(20, -18); g.arc(12, -18, 8, 0, TAU); g.moveTo(-4, -18); g.lineTo(4, -18); g.stroke();
