function escapeHtml(s) { return String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])); }
/* ============================ POLIMENTO: tela de resultado e comemorações ============================
   Fim de corrida, entrega ou percurso: um cartão aparece no alto (sem parar o jogo) com as estrelas uma a uma,
   os valores subindo em contador animado com som e o total em destaque. Some sozinho em ~5 s. */
const Resultado = { el: null, timers: [] };
Resultado.cria = function () {
  if (this.el) return this.el;
  const el = this.el = document.createElement('div'); el.id = 'resultado'; el.className = 'hidden';
  document.body.appendChild(el); return el;
};
Resultado.limpa = function () { for (const t of this.timers) clearTimeout(t); this.timers = []; };
// o: { titulo, sub, estrelas (0-5 ou null), medalha (texto ou null), linhas: [[rótulo, valor]], total }
Resultado.mostra = function (o) {
  const el = this.cria(); this.limpa();
  const linhas = (o.linhas || []).filter((l) => l[1]);
  el.innerHTML = `<div class="rs-top"><b>${escapeHtml(o.titulo)}</b>${o.sub ? `<small>${escapeHtml(o.sub)}</small>` : ''}</div>` +
    (o.estrelas !== null && o.estrelas !== undefined ? `<div class="rs-stars">${[0, 1, 2, 3, 4].map((i) => `<i data-s="${i}"></i>`).join('')}</div>` : '') +
    (o.medalha ? `<div class="rs-medal m${o.medalhaN || 0}">${escapeHtml(o.medalha)}</div>` : '') +
    `<div class="rs-lines">${linhas.map((l, i) => `<div class="rs-l" data-l="${i}"><span>${escapeHtml(l[0])}</span><em>R$ 0</em></div>`).join('')}</div>` +
    `<div class="rs-total"><span>Total</span><em>R$ 0</em></div>`;
  el.classList.remove('hidden', 'sai'); void el.offsetWidth; el.classList.add('entra');
  const at = (ms, fn) => this.timers.push(setTimeout(fn, ms));
  let t = 250;
  // estrelas: uma de cada vez, com nota subindo
  if (o.estrelas !== null && o.estrelas !== undefined) {
    for (let i = 0; i < 5; i++) {
      const ok = i < o.estrelas;
      at(t, () => { const s = el.querySelector(`[data-s="${i}"]`); if (s) s.classList.add(ok ? 'on' : 'off'); if (ok) AudioSys.tone(660 + i * 120, 0.09, 'triangle', 0.06, 'ui'); });
      t += ok ? 170 : 90;
    }
    t += 150;
  }
  // valores subindo
  const conta = (sel, v, dur, fim) => {
    const box = el.querySelector(sel); if (!box) return; const e = box.querySelector('em'); box.classList.add('on');
    const n = Math.max(6, Math.round(dur / 45));
    for (let k = 1; k <= n; k++) at(t + (dur * k) / n, () => { e.textContent = 'R$ ' + fmtMoney(Math.round(v * k / n)); if (k % 2 === 0) AudioSys.tone(1500, 0.02, 'square', 0.015, 'ui'); if (k === n && fim) fim(); });
    t += dur + 90;
  };
  linhas.forEach((l, i) => conta(`[data-l="${i}"]`, l[1], 420));
  conta('.rs-total', o.total, 520, () => { AudioSys.money(); el.querySelector('.rs-total').classList.add('pop'); });
  at(t + 3200, () => { el.classList.add('sai'); });
  at(t + 3700, () => { el.classList.add('hidden'); el.classList.remove('entra', 'sai'); });
};

// confete na subida de nível (pedacinhos coloridos caindo, só por cima da tela, some sozinho)
function confete(n) {
  const box = document.createElement('div'); box.className = 'confete'; document.body.appendChild(box);
  const cores = ['#ffd23f', '#3ad07a', '#3a9be0', '#ff5a5a', '#ff8ad8', '#ffffff'];
  for (let i = 0; i < (n || 70); i++) {
    const p = document.createElement('i');
    p.style.left = (50 + (Math.random() - 0.5) * 70) + '%'; p.style.background = cores[i % cores.length];
    p.style.animationDelay = (Math.random() * 0.35).toFixed(2) + 's'; p.style.animationDuration = (1.6 + Math.random() * 1.2).toFixed(2) + 's';
    p.style.setProperty('--dx', ((Math.random() - 0.5) * 340).toFixed(0) + 'px'); p.style.setProperty('--rz', ((Math.random() - 0.5) * 900).toFixed(0) + 'deg');
    box.appendChild(p);
  }
  setTimeout(() => box.remove(), 3400);
}

/* ---------- avisos de missão em estilo de cinema: título do capítulo, legenda do objetivo,
   caixa de ajuda no canto e a faixa de "capítulo concluído" ---------- */
const Missao = { timers: {} };
Missao.el = function (id) {
  let e = $(id);
  if (!e) { e = document.createElement('div'); e.id = id; e.className = 'ms-oculto'; document.body.appendChild(e); }
  return e;
};
Missao.mostra = function (id, html, seg) {
  const e = this.el(id);
  e.innerHTML = html; e.classList.remove('ms-sai', 'ms-oculto'); void e.offsetWidth; e.classList.add('ms-on');
  clearTimeout(this.timers[id]);
  if (seg) this.timers[id] = setTimeout(() => this.esconde(id), seg * 1000);
};
Missao.esconde = function (id) {
  const e = $(id); if (!e || e.classList.contains('ms-oculto')) return;
  e.classList.add('ms-sai'); clearTimeout(this.timers[id]);
  this.timers[id] = setTimeout(() => { e.classList.remove('ms-on', 'ms-sai'); e.classList.add('ms-oculto'); }, 600);
};
// nome do capítulo grande no meio da tela
Missao.titulo = function (rotulo, nome, historia) {
  this.mostra('ms-titulo', `<div class="ms-rot">${escapeHtml(rotulo)}</div><div class="ms-nome">${escapeHtml(nome)}</div>` + (historia ? `<div class="ms-hist">${escapeHtml(historia)}</div>` : ''), historia ? 6.5 : 4.5);
  try { [196, 294, 392].forEach((f, i) => AudioSys.tone(f, 1.4, 'triangle', 0.05, 'ui', null, i * 0.12)); } catch (e) {}
};
// objetivo como legenda embaixo (palavra importante em amarelo)
Missao.legenda = function (html, seg, quem) {
  this.mostra('ms-legenda', (quem ? `<span class="ms-quem">${escapeHtml(quem)}:</span> ` : '') + html, seg || 7);
};
// caixa de ajuda no canto de cima
Missao.ajuda = function (html, seg) {
  this.mostra('ms-ajuda', html, seg || 8);
  try { AudioSys.tone(880, 0.12, 'sine', 0.05, 'ui'); AudioSys.tone(1320, 0.16, 'sine', 0.04, 'ui', null, 0.08); } catch (e) {}
};
// faixa escura atravessando a tela com "CAPÍTULO CONCLUÍDO"
Missao.passou = function (titulo, sub, valor) {
  this.mostra('ms-passou', `<div class="ms-faixa"><div class="ms-ok">${escapeHtml(titulo)}</div><div class="ms-sub">${escapeHtml(sub)}</div>${valor ? `<div class="ms-val">+ R$ ${fmtMoney(valor)}</div>` : ''}</div>`, 5.5);
  try { [[523, 0], [659, 0.1], [784, 0.2], [1047, 0.32], [784, 0.62], [1047, 0.74], [1319, 0.86]].forEach(([f, d]) => AudioSys.tone(f, 0.55, 'triangle', 0.07, 'ui', null, d)); } catch (e) {}
};

// nome do lugar no canto de baixo (apresentação da missão)
Missao.lugar = function (nome, sub, tag) {
  this.mostra('ms-lugar', (tag ? `<div class="ml-tag">${escapeHtml(tag)}</div>` : '') + `<div class="ml-nome">${escapeHtml(nome)}</div>` + (sub ? `<div class="ml-sub">${escapeHtml(sub)}</div>` : ''), 0);
  try { AudioSys.tone(523, 0.25, 'sine', 0.04, 'ui'); AudioSys.tone(784, 0.35, 'sine', 0.035, 'ui', null, 0.1); } catch (e) {}
};

// missão fracassada (desistiu pelo menu): faixa escura com o texto em vermelho
Missao.fracassou = function (sub) {
  this.mostra('ms-passou', `<div class="ms-faixa"><div class="ms-ok ms-falhou">Missão fracassada</div><div class="ms-sub">${escapeHtml(sub || '')}</div></div>`, 4.5);
  try { [[392, 0], [330, 0.18], [262, 0.36], [196, 0.6]].forEach(([f, d]) => AudioSys.tone(f, 0.6, 'triangle', 0.07, 'ui', null, d)); } catch (e) {}
};
/* ============================ HISTÓRIA: O CARRO DOS SONHOS ============================
   7 capítulos + o final. No fundo da oficina do Seu Zé tem um Opalha 6C preto à venda (R$ 35.000; R$ 29.000 com o
   desconto de quem ajudou o Juninho, o dono do outro Opalha, que empresta o carro dele para o racha):
   cada capítulo abre com um áudio do Seu Zé no zap, tem uma meta, paga um prêmio e leva ao próximo.
   O progresso conta a partir do começo do capítulo (Profile.hist = { cap, base }). */
const SONHO = 'brasa'; // Opalha 6C
const CAP_FINAL = 7; // 7 capítulos (0 a 6); a história termina quando ganha o racha (sem missão de juntar dinheiro)
const capNome = (i) => (i >= CAP_FINAL ? 'Final' : 'Capítulo ' + (i + 1));
// preço do Opalha: R$ 35.000; quem ajudou o Juninho paga R$ 29.000
const OPALHA_CHEIO = 35000, OPALHA_AMIGO = 29000;
function precoCarro(c) { return c && c.id === SONHO && Profile.hist && Profile.hist.juninho ? OPALHA_AMIGO : c ? c.price : 0; }
function descontoCarro(c) { return c ? c.price - precoCarro(c) : 0; }
const corridasDe = () => Profile.rides || 0;
// o que liga cada capítulo ao anterior (aparece embaixo do nome do capítulo e na pausa)
const HIST_PORQUE = [
  'Você chegou em São Gambiarra com um Gou Quadrado velho e um sonho: o Opalha 6C do fundo da oficina do Seu Zé.',
  'Pra comprar o Opalha, primeiro o dinheiro. O Seu Zé te cadastrou no PegaAí.',
  'As corridas ajudaram, mas o Opalha custa caro. Os comércios estão precisando de entregador.',
  'O Seu Zé diz que quem ajuda a cidade é ajudado. De madrugada sempre tem alguém em apuros.',
  'Agora a cidade te conhece. Falta provar que você também dirige na terra, lá na roça.',
  'O Zé do Canecão te desafiou pro racha, mas o Gou Quadrado não aguenta. O Juninho tem um Opalha parado...',
  'O Juninho te emprestou o Opalha dele. Hora de calar a boca do Zé do Canecão.',
];
const HIST_CAPS = [
  { nome: 'Chegada', leg: 'Siga o <b>Seu Zé</b> no passo a passo.', dica: '', meta: 'Termine o passo a passo com o Seu Zé.', voz: null, premio: 200,
    val: () => (Profile.tut === undefined || Profile.tut >= TUT_STEPS.length ? 1 : 0), alvo: 1, absoluto: true },
  { nome: 'Ganha-pão', leg: 'Faça <b>5 corridas</b> no <b>PegaAí</b>.', dica: 'Abra o celular com <kbd>Q</kbd> e fique <b>online</b> no PegaAí.', meta: 'Faça corridas no PegaAí.', voz: 'cap_2', premio: 400, val: corridasDe, alvo: 5 },
  { nome: 'Entregador da madrugada', leg: 'Faça <b>3 entregas</b> dos comércios ou fretes.', dica: 'Comércios com marcador <b>amarelo</b> têm entrega: pare na frente e aperte <kbd>E</kbd>. Fretes ficam no app <b>Fretes</b>.', meta: 'Faça entregas dos comércios ou fretes.', voz: 'cap_3', premio: 500, val: () => Profile.deliveries || 0, alvo: 3 },
  { nome: 'Socorro na madrugada', leg: 'Ajude <b>2 pessoas</b> nos eventos da cidade.', dica: 'Quando chegar um pedido de ajuda na tela, aperte <kbd>Y</kbd> para aceitar.', meta: 'Ajude gente nos eventos da cidade (fique de olho no celular).', voz: 'cap_4', premio: 700, val: () => Profile.evTotal || 0, alvo: 2 },
  { nome: 'A estrada da roça', leg: 'Vá até a <b>fazenda</b> e termine o <b>Rali da Vaca Atolada</b>.', dica: 'O <b>GPS</b> já marca a largada do rali. Pare na bandeira e aperte <kbd>E</kbd>.', meta: 'Termine o Rali da Vaca Atolada, lá na fazenda.', voz: 'cap_5', premio: 900,
    val: () => Profile.histRali || 0, alvo: 1, absoluto: true,
    alvoMapa: () => { const r = World.races.find((q) => q.id === 'fazenda'); return r && { x: r.start[0], y: r.start[1], label: 'Rali da Vaca Atolada' }; } },
  { nome: 'O dono do Opalha', leg: 'O Opalha do <b>Juninho</b> morreu na rua: vá lá e dê uma <b>chupeta</b>.', dica: 'O Gou Quadrado não ganha do carro do Zé do Canecão. Ajude o <b>Juninho</b> e ele te empresta o <b>Opalha</b> pro racha.', meta: 'Ajude o Juninho com o Opalha parado (siga o ponto rosa).', voz: 'cap_opalha', premio: 600,
    val: () => (Profile.hist && Profile.hist.juninho ? 1 : 0), alvo: 1, absoluto: true },
  { nome: 'Tudo ou nada', leg: 'Ganhe o <b>racha</b> do <b>Zé do Canecão</b> com o Opalha emprestado.', dica: 'Rachas acontecem das <b>22h às 4h30</b>. Veja no app <b>Racha</b> do celular. Depois o Opalha volta pro Juninho.', meta: 'Ganhe um racha de madrugada (das 22h às 4h30) com o Opalha do Juninho.', voz: 'cap_6', premio: 1500, val: () => Profile.rachaWins || 0, alvo: 1 },
];
const Historia = {
  t: 0, popT: 0,
  h() {
    if (!Profile.hist) {
      // quem já jogava antes da história começa no capítulo 2 (o passo a passo não existia)
      const veterano = Profile.tut === undefined && (Profile.rides || Profile.deliveries || Profile.earned);
      Profile.hist = { cap: veterano ? 1 : 0, base: 0, fim: false, v: 4 };
      if (veterano) { Profile.hist.base = this.cru(1); Profile.hist.anunciar = true; Profile.hist.tudo = true; Profile.hist.apres = true; }
    }
    // história começada na versão anterior (sem travas): quem já jogava continua com tudo liberado e sem a apresentação inicial
    if (Profile.hist.v === undefined) { Profile.hist.v = 2; Profile.hist.apres = true; if (Profile.rides || Profile.deliveries || Profile.earned > 0) Profile.hist.tudo = true; }
    // v3 (nov/2026): entrou o capítulo do Juninho antes do racha; quem já estava no racha ou no final pula ele (e ganha o desconto)
    if (Profile.hist.v === 2) { Profile.hist.v = 3; if (Profile.hist.cap >= 5) { Profile.hist.cap++; Profile.hist.juninho = true; } }
    // v4: saiu o capítulo final de juntar dinheiro: quem estava nele já terminou a história
    if (Profile.hist.v === 3) { Profile.hist.v = 4; if (Profile.hist.cap >= CAP_FINAL) Profile.hist.fim = true; }
    return Profile.hist;
  },
  cru(i) { const c = HIST_CAPS[i]; return c ? c.val() : 0; },
  cap() { const h = this.h(); return h.fim ? null : HIST_CAPS[h.cap]; },
  feito() { const h = this.h(), c = HIST_CAPS[h.cap]; if (!c) return 0; return Math.max(0, c.absoluto ? c.val() : c.val() - h.base); },
  // linha do painel de objetivo (quando não tem corrida, entrega ou evento)
  hud() {
    const h = this.h(), c = this.cap(); if (!c || h.cap === 0) return null;
    const f = Math.min(c.alvo, this.feito());
    let det = c.extra ? c.extra() : c.alvo > 1 ? f + ' de ' + c.alvo : '';
    if (h.cap === 6 && !rachaOpen()) det = 'o racha abre às 22h (agora ' + clockStr() + ')';
    if (h.cap === 5 && Events.cur && Events.cur.opalha && !Events.cur.over) det = 'siga o ponto rosa e aperte E';
    return [c.nome, c.meta, (det ? det + ' · ' : '') + (c.premio ? 'prêmio R$ ' + fmtMoney(c.premio) : '')];
  },
  update(dt) {
    this.rastro();
    if (Game.mode !== 'play' || !carregou(1)) return;
    const h = this.h(); if (h.fim) return;
    this.t -= dt; if (this.t > 0) return; this.t = 0.5;
    if (h.anunciar) { if (VoicePlayer.msg || Screens.current === 'screen-dialog' || Apresenta.on) return; h.anunciar = false; this.abre(h.cap); return; }
    if (h.cap === 0 && !h.apres) { // primeira noite: a câmera apresenta a cidade, a oficina e a garagem; depois começa o passo a passo
      h.apres = true; saveGame();
      Apresenta.comeca(lugaresDoCapitulo(0), () => { Missao.titulo('Capítulo 1 de ' + CAP_FINAL, 'Chegada'); });
      return;
    }
    if (Apresenta.on) return;
    if (Profile.tut !== undefined && Profile.tut < TUT_STEPS.length && h.cap === 0) return;
    if (!HIST_CAPS[h.cap]) { this.final(); return; } // capítulo que não existe mais (save antigo): história concluída
    const c = HIST_CAPS[h.cap], f = this.feito();
    // avanço do capítulo aparece como legenda (sem quadro fixo na tela)
    if (h.cap > 0 && c.alvo > 1 && f > (this.ultimo === undefined ? f : this.ultimo) && f < c.alvo && telaLivre() && !Apresenta.on && !document.querySelector('#ms-titulo.ms-on:not(.ms-sai)')) Missao.legenda(escapeHtml(c.nome) + ': <b>' + f + ' de ' + c.alvo + '</b>', 5);
    this.ultimo = f;
    if (f >= c.alvo) { this.ultimo = undefined; this.conclui(); }
  },
  conclui() {
    const h = this.h(), c = HIST_CAPS[h.cap], n = h.cap + 1;
    if (c.premio) pay(c.premio);
    if (h.cap === HIST_CAPS.length - 1) { this.final(); return; }
    Missao.passou('Missão cumprida', c.nome, c.premio); confete(60);
    h.cap++; h.base = this.cru(h.cap);
    if (h.cap === 4) Profile.histRali = 0;
    if (h.cap === 7) Emprestimo.devolve(); // ganhou o racha: o Opalha volta para o Juninho
    saveGame();
    clearTimeout(this.abreT); this.abreT = setTimeout(() => this.abre(h.cap), 6500); // só um (pular várias seguidas não abre repetido)
  },
  // começa um capítulo: nome grande no meio, objetivo em legenda, dica no canto e áudio do Seu Zé no zap
  abre(i, recomeco) {
    const c = HIST_CAPS[i]; if (!c || Game.mode !== 'play') return;
    if (!recomeco && c.voz && CHAR_VOICES[c.voz]) { const m = charVoice(c.voz); if (m && m.voice) setTimeout(() => VoicePlayer.play(m), 900); }
    if (c.alvoMapa) { const w = c.alvoMapa(); if (w) { Act.waypoint = w; Act.gpsT = 0; } }
    this.guia(i);
    if (i === 3) MissaoAjuda.t = 14; // o pedido de ajuda começa logo depois do título
    if (i === 5) MissaoOpalha.nasce(); // o Opalha do Juninho já aparece parado na rua (a câmera mostra onde)
    if (i === 6) Emprestimo.empresta(); // o Juninho empresta o Opalha para o racha
    this.ultimo = undefined;
    saveGame();
    Apresenta.comeca(recomeco ? [] : lugaresDoCapitulo(i), () => {
      if (Game.mode !== 'play') return;
      Missao.titulo(i >= CAP_FINAL ? 'O final' : 'Capítulo ' + (i + 1) + ' de ' + CAP_FINAL, c.nome, recomeco ? 'Tentando de novo.' : HIST_PORQUE[i]);
      // (sem legenda do objetivo: o quadro de missão no topo já mostra)
      const lib = recomeco ? [] : Object.keys(LIBERA).filter((k) => LIBERA[k] === i).map((k) => LIBERA_NOME[k]);
      const dica = (lib.length ? '<div class="ms-ajuda-tit">Liberado</div><b>' + lib.join('</b> · <b>') + '</b><br>' : '') + (c.dica || '');
      if (dica) setTimeout(() => { if (Game.mode === 'play') Missao.ajuda(dica, 10); }, 7400);
      if (i === 3) MissaoAjuda.t = 6;
    });
  },
  // GPS já apontando para onde a missão acontece (quando tem um lugar certo)
  guia(i) {
    let w = null;
    if (i === 2) { const s = World.shops.filter((q) => q.pickup).sort((a, b) => Math.hypot(a.x - player.x, a.y - player.y) - Math.hypot(b.x - player.x, b.y - player.y))[0]; if (s) w = { x: s.x, y: s.y, label: 'Entrega: ' + s.name }; }
    if (i === 6) { const r = World.rachas && World.rachas[0]; if (r) w = { x: r.start[0], y: r.start[1], label: 'Racha: ' + r.name }; }
    if (i === 7 && World.home) w = { x: World.home.x, y: World.home.y, label: 'Sua garagem' };
    if (w) { Act.waypoint = w; Act.gpsT = 0; }
  },
  ativa() { const h = Profile.hist; return !!(h && !h.fim && h.cap > 0 && !Apresenta.on); },
  // desistiu pelo menu (Abandonar atividade): missão fracassada e o capítulo recomeça do zero depois de uns segundos
  desiste() {
    const h = this.h(), c = HIST_CAPS[h.cap]; if (!c || h.fim || h.cap === 0) return false;
    Missao.esconde('ms-titulo'); Missao.esconde('ms-legenda'); Missao.esconde('ms-ajuda');
    Missao.fracassou(c.nome);
    if (Events.cur && Events.cur.missao) Events.clear();
    if (h.cap === 4) Profile.histRali = 0;
    if (Profile.emprestimo) Emprestimo.devolve(true);
    Act.waypoint = null; Act.gps = null;
    h.base = this.cru(h.cap); this.ultimo = undefined;
    saveGame();
    clearTimeout(this.reT); this.reT = setTimeout(() => { if (Game.mode === 'play' && !h.fim) this.abre(h.cap, true); }, 6000);
    return true;
  },
  // rastreador no canto (embaixo do nome do bairro): o que fazer agora e quanto falta
  rastro() {
    const h = Profile.hist, el = $('missao-trk');
    const mostra = false; // substituído pelo quadro de objetivo (só em missão)
    if (!el) return;
    el.classList.toggle('hidden', !mostra); document.body.classList.toggle('com-trk', !!mostra);
    if (!mostra) return;
    const c = HIST_CAPS[h.cap], f = Math.min(c.alvo, this.feito());
    let det = c.extra ? c.extra() : c.alvo > 1 ? f + ' de ' + c.alvo : '';
    if (h.cap === 6 && !rachaOpen()) det = 'O racha abre às 22h (agora ' + clockStr() + ')';
    if (h.cap === 5 && Events.cur && Events.cur.opalha && !Events.cur.over) det = 'Siga o ponto rosa no GPS e aperte E';
    const html = `<small>Missão · ${escapeHtml(capNome(h.cap))}</small><b>${escapeHtml(c.nome)}</b><span>${escapeHtml(c.meta)}${det ? ' · <em>' + escapeHtml(det) + '</em>' : ''}</span>`;
    if (el.innerHTML !== html) el.innerHTML = html;
  },
  final() {
    const h = this.h(); h.fim = true;
    if (Profile.emprestimo) Emprestimo.devolve();
    saveGame(); confete(160);
    Missao.passou('História concluída', 'Você venceu o Zé do Canecão com o Opalha do Juninho. Agora a cidade é sua.', 0);
    try { AudioSys.chime(); setTimeout(() => AudioSys.chime(), 350); } catch (e) {}
  },
  // trapaça do dono: cumpre a missão atual na hora (para testar a história)
  pula() {
    const h = this.h(); if (h.fim) return false;
    if (Apresenta.on) Apresenta.encerra();
    if (h.cap === 0) Profile.tut = TUT_STEPS.length;
    if (h.cap === 5) h.juninho = true;
    if (Events.cur && Events.cur.missao) Events.clear();
    clearTimeout(this.reT); this.ultimo = undefined;
    this.conclui(); return true;
  },
  // tela de pausa: lista dos capítulos
  // pausa: o capítulo de agora em destaque e a história inteira numa linha de passos
  pausaHTML() {
    const h = this.h(), c = HIST_CAPS[h.cap];
    const passos = HIST_CAPS.map((k, i) => {
      const st = h.fim || i < h.cap ? 'ok' : i === h.cap ? 'at' : '';
      return `<i class="hp-passo ${st}" title="${escapeHtml(k.nome)}">${i + 1}</i>`;
    }).join('<s class="hp-liga"></s>');
    let card;
    if (h.fim || !c) card = '<div class="hp-card fim"><small>O carro dos sonhos</small><b>História concluída</b><p>Agora a cidade é sua.</p></div>';
    else {
      const f = Math.min(c.alvo, this.feito());
      let det = c.extra ? c.extra() : c.alvo > 1 ? f + ' de ' + c.alvo : '';
      if (h.cap === 6 && !rachaOpen()) det = 'o racha abre às 22h';
      card = `<div class="hp-card"><small>Capítulo ${h.cap + 1} de ${CAP_FINAL}</small><b>${escapeHtml(c.nome)}</b>` +
        `<p class="hp-porque">${escapeHtml(HIST_PORQUE[h.cap] || '')}</p>` +
        `<p class="hp-agora"><span>O que fazer</span>${escapeHtml(c.meta)}${det ? ' <em>' + escapeHtml(det) + '</em>' : ''}</p>` +
        (c.premio ? `<p class="hp-premio">Prêmio: R$ ${fmtMoney(c.premio)}</p>` : '') + '</div>';
    }
    return card + `<div class="hp-linha"><span>História</span><div class="hp-passos">${passos}</div></div>`;
  },
  listaHTML() {
    const h = this.h();
    return HIST_CAPS.map((c, i) => {
      const st = h.fim || i < h.cap ? 'ok' : i === h.cap ? 'at' : '';
      return `<div class="hist-cap ${st}"><b>${i >= CAP_FINAL ? 'F' : i + 1}</b><span>${escapeHtml(c.nome)}</span></div>`;
    }).join('') + (h.fim ? '' : `<div class="hist-agora"><em>${escapeHtml(HIST_PORQUE[h.cap] || '')}</em><b>Agora:</b> ${escapeHtml((HIST_CAPS[h.cap] || {}).meta || '')}</div>`);
  },
};
/* ============================ MISSÕES: APRESENTAÇÃO DOS LUGARES, MAPA EXPLORADO E FUNÇÕES LIBERADAS ============================
   - Apresenta: no começo de cada capítulo a câmera viaja (com faixas de cinema) até os lugares importantes, mostra o nome
     de cada um e volta para o carro. O jogo fica parado no lugar (carro freado). Enter, Espaço, Esc ou "Pular" encerra.
   - Nevoa: o mapa do celular começa escuro e vai abrindo por onde o jogador passa (e pelos lugares que a missão mostra).
   - liberado(): Fretes, entregas, eventos, percursos e racha vão sendo liberados pelos capítulos da história. */

/* ---------- funções liberadas pela história ---------- */
// capítulo (índice de HIST_CAPS) em que cada coisa fica liberada
const LIBERA = { camera: 1, colecao: 1, entregas: 2, fretes: 2, eventos: 3, percursos: 4, racha: 6 };
const LIBERA_NOME = { camera: 'App Câmera', colecao: 'App Coleção', entregas: 'Entregas nos comércios', fretes: 'App Fretes', eventos: 'Pedidos de ajuda pela cidade', percursos: 'Percursos cronometrados', racha: 'Racha da madrugada' };
function liberado(f) {
  if (navigator.webdriver && !window.__travas) return true; // testes e gravadores de vídeo antigos: tudo liberado
  const h = Profile.hist;
  if (!h || h.fim || h.tudo) return true;
  if (f === 'pegaai') return h.cap > 0 || Profile.tut === undefined || Profile.tut >= 3; // o tutorial libera o PegaAí no passo do celular
  return h.cap >= (LIBERA[f] || 0);
}
function travaTexto(f) { return 'Libera no Capítulo ' + ((LIBERA[f] || 0) + 1) + ' da história'; }

/* ---------- mapa explorado (névoa) ---------- */
const NEV_C = 250, NEV_W = Math.ceil(WORLD_W / NEV_C), NEV_H = Math.ceil(WORLD_H / NEV_C);
const Nevoa = { a: null, cv: null, sujo: true, t: 0 };
Nevoa.carrega = function () {
  const N = NEV_W * NEV_H;
  if (typeof Profile.nevoa !== 'string' || Profile.nevoa.length !== N) {
    // quem já jogava antes do mapa explorado fica com o mapa inteiro aberto
    const veterano = !!(Profile.rides || Profile.deliveries || Profile.earned || (Profile.hist && Profile.hist.tudo));
    Profile.nevoa = (veterano ? '1' : '0').repeat(N);
  }
  this.a = new Uint8Array(N);
  for (let i = 0; i < N; i++) this.a[i] = Profile.nevoa.charCodeAt(i) === 49 ? 1 : 0;
  this.sujo = true;
};
Nevoa.revela = function (x, y, r) {
  if (!this.a) return 0;
  let n = 0;
  const g0 = Math.max(0, Math.floor((x - r) / NEV_C)), g1 = Math.min(NEV_W - 1, Math.floor((x + r) / NEV_C));
  const h0 = Math.max(0, Math.floor((y - r) / NEV_C)), h1 = Math.min(NEV_H - 1, Math.floor((y + r) / NEV_C));
  for (let gy = h0; gy <= h1; gy++) for (let gx = g0; gx <= g1; gx++) {
    const i = gy * NEV_W + gx;
    if (this.a[i]) continue;
    if (Math.hypot(gx * NEV_C + NEV_C / 2 - x, gy * NEV_C + NEV_C / 2 - y) > r) continue;
    this.a[i] = 1; n++;
  }
  if (n) { this.sujo = true; let s = ''; for (let i = 0; i < this.a.length; i++) s += this.a[i] ? '1' : '0'; Profile.nevoa = s; }
  return n;
};
Nevoa.aberto = function (x, y) {
  if (!this.a) return true;
  const gx = Math.floor(x / NEV_C), gy = Math.floor(y / NEV_C);
  if (gx < 0 || gy < 0 || gx >= NEV_W || gy >= NEV_H) return true;
  return !!this.a[gy * NEV_W + gx];
};
Nevoa.pct = function () { if (!this.a) return 100; let n = 0; for (const v of this.a) n += v; return Math.round(n / this.a.length * 100); };
// imagem pequena (uma casinha por pixel) esticada sobre o mapa com suavização: a borda da névoa fica macia
Nevoa.img = function () {
  if (!this.a) return null;
  if (!this.cv) { this.cv = document.createElement('canvas'); this.cv.width = NEV_W + 2; this.cv.height = NEV_H + 2; }
  if (this.sujo) {
    const g = this.cv.getContext('2d'), im = g.createImageData(NEV_W + 2, NEV_H + 2), d = im.data;
    for (let y = 0; y < NEV_H + 2; y++) for (let x = 0; x < NEV_W + 2; x++) {
      const gx = clamp(x - 1, 0, NEV_W - 1), gy = clamp(y - 1, 0, NEV_H - 1), o = (y * (NEV_W + 2) + x) * 4;
      d[o] = 10; d[o + 1] = 12; d[o + 2] = 16; d[o + 3] = this.a[gy * NEV_W + gx] ? 0 : 252; // área não explorada: quase preta, bloqueada
    }
    g.putImageData(im, 0, 0); this.sujo = false;
  }
  return this.cv;
};
Nevoa.desenha = function (g) {
  const im = this.img(); if (!im) return;
  g.save(); g.imageSmoothingEnabled = true;
  g.drawImage(im, -NEV_C, -NEV_C, (NEV_W + 2) * NEV_C, (NEV_H + 2) * NEV_C);
  g.restore();
};
Nevoa.update = function (dt) {
  if (!player || Game.mode !== 'play') return;
  this.t -= dt; if (this.t > 0) return; this.t = 0.5;
  this.revela(player.x, player.y, 650);
};

/* ---------- apresentação dos lugares (câmera de cinema) ---------- */
const Apresenta = { on: false, fila: [], i: 0, t: 0, fase: 'ida', ox: 0, oy: 0, z0: 1, fim: null, dur: 2 };
Apresenta.comeca = function (lugares, fim) {
  lugares = (lugares || []).filter((q) => q && isFinite(q.x) && isFinite(q.y));
  if (navigator.webdriver && !window.__intro) lugares = []; // testes e gravadores antigos: sem viagem de câmera
  if (!lugares.length || !player || Game.mode !== 'play') { if (fim) fim(); return; }
  this.on = true; this.fila = lugares; this.i = 0; this.fim = fim || null;
  this.z0 = Cam.zoom; this.prox(Cam.x, Cam.y);
  document.body.classList.add('cinema');
  let el = $('cine');
  if (!el) {
    el = document.createElement('div'); el.id = 'cine';
    el.innerHTML = '<i class="cn-top"></i><i class="cn-bot"></i><button id="cine-pular" type="button">Pular <kbd>Enter</kbd></button>';
    document.body.appendChild(el);
    el.querySelector('#cine-pular').addEventListener('click', () => this.pula());
  }
  el.classList.remove('sai'); el.classList.add('on');
  try { AudioSys.tone(220, 1.2, 'triangle', 0.035, 'ui'); AudioSys.tone(330, 1.2, 'triangle', 0.03, 'ui', null, 0.15); } catch (e) {}
};
Apresenta.prox = function (fx, fy) {
  const q = this.fila[this.i];
  this.ox = fx; this.oy = fy; this.t = 0; this.fase = 'ida';
  const tx = q ? q.x : player.x, ty = q ? q.y : player.y;
  this.dur = clamp(Math.hypot(tx - fx, ty - fy) / 2600, 1.1, 2.6);
};
Apresenta.update = function (dt) {
  if (!this.on) return false;
  if (!player || Game.mode !== 'play') { this.encerra(); return false; }
  this.t += dt;
  const q = this.fila[this.i], volta = !q;
  const tx = volta ? player.x : q.x, ty = volta ? player.y : q.y;
  if (this.fase === 'ida') {
    const u = clamp(this.t / this.dur, 0, 1), e = u * u * (3 - 2 * u);
    Cam.x = lerp(this.ox, tx, e); Cam.y = lerp(this.oy, ty, e);
    Cam.zoom = this.z0 * (1 - 0.32 * Math.sin(Math.PI * u) * clamp(this.dur / 1.6, 0.4, 1));
    if (u >= 1) {
      if (volta) { this.encerra(); return false; }
      this.fase = 'olha'; this.t = 0;
      Nevoa.revela(q.x, q.y, q.r || 700);
      Missao.lugar(q.nome, q.sub || '', q.tag || '');
    }
  } else {
    Cam.x = tx + Math.sin(this.t * 0.35) * 18; Cam.y = ty - this.t * 6; Cam.zoom = this.z0 * 1.04;
    if (this.t > (q.seg || 3.4)) { Missao.esconde('ms-lugar'); this.i++; this.prox(Cam.x, Cam.y); }
  }
  return true;
};
Apresenta.pula = function () {
  if (!this.on) return;
  for (let k = this.i; k < this.fila.length; k++) { const q = this.fila[k]; Nevoa.revela(q.x, q.y, q.r || 700); }
  this.encerra();
};
Apresenta.encerra = function () {
  if (!this.on) return;
  this.on = false; Missao.esconde('ms-lugar');
  if (player) { Cam.x = player.x; Cam.y = player.y; Cam.zoom = this.z0; }
  document.body.classList.remove('cinema');
  const el = $('cine'); if (el) { el.classList.add('sai'); setTimeout(() => { if (!this.on) el.classList.remove('on', 'sai'); }, 500); }
  const f = this.fim; this.fim = null; this.fila = [];
  if (f) setTimeout(f, 250);
};

/* ---------- lugares de cada capítulo ---------- */
function lugarShop(kind, nome, sub, tag) {
  const ss = World.shops.filter((s) => s.kind === kind);
  if (!ss.length) return null;
  const s = ss.sort((a, b) => Math.hypot(a.x - player.x, a.y - player.y) - Math.hypot(b.x - player.x, b.y - player.y))[0];
  return { x: s.x, y: s.y, nome: nome || s.name, sub, tag };
}
function lugaresDoCapitulo(i) {
  const poi = (id) => World.pois.find((p) => p.id === id);
  const P = (p, nome, sub, tag) => p && { x: p.x, y: p.y, nome: nome || p.name, sub, tag };
  const of = oficinaZe(), home = World.home;
  switch (i) {
    case 0: return [
      P(poi('praca'), 'São Gambiarra', 'A cidade que nunca dorme. E nunca paga em dia.', 'Bem-vindo'),
      of && { x: of.x, y: of.y, nome: 'Oficina do Seu Zé', sub: 'Conserto, socorro de madrugada e fiado (com juros de carinho).', tag: 'Oficina' },
      home && { x: home.x, y: home.y, nome: 'Sua garagem', sub: 'Troque de carro, pinte e personalize.', tag: 'Garagem' },
    ];
    case 1: return [P(poi('praca'), 'Centrão', 'Onde mais aparece passageiro do PegaAí.', 'Corridas')];
    case 2: return [
      lugarShop('padaria', null, 'Comércio com marcador amarelo tem entrega: pare na frente e aperte E.', 'Entregas'),
      (() => { const d = World.depots && Object.values(World.depots)[0]; return d && { x: d.x, y: d.y, nome: d.name, sub: 'Fretes de caminhão: gás, baú, caçamba e reboque.', tag: 'Fretes' }; })(),
    ];
    case 4: {
      const r = World.races.find((q) => q.id === 'fazenda');
      return [P(poi('fazenda'), 'Fazenda Muuuito Longe', 'Leite, queijo, vaca e lama até o joelho.', 'A roça'),
        r && { x: r.start[0], y: r.start[1], nome: 'Rali da Vaca Atolada', sub: 'A largada é aqui. Pare na bandeira e aperte E.', tag: 'Percurso' }];
    }
    case 5: { // o Opalha do Juninho parado na rua
      const E = Events.cur;
      return [E && E.opalha && { x: E.x, y: E.y, nome: 'Juninho e o Opalha', sub: 'A bateria arriou. Encoste do lado e aperte E para a chupeta.', tag: 'Ajude' }];
    }
    case 6: {
      const r = World.rachas && World.rachas[0];
      return [r && { x: r.start[0], y: r.start[1], nome: r.name, sub: 'Das 22h às 4h30. Aposta contra ' + r.rival + '.', tag: 'Racha' }];
    }
    case 7: return [of && { x: of.x, y: of.y, nome: 'O Opalha 6C', sub: 'Encerado, de tanque cheio, esperando no fundo da oficina.', tag: 'O sonho' }];
  }
  return [];
}

/* ---------- capítulo 4: o pedido de ajuda começa na hora, e o segundo logo depois do primeiro ---------- */
const AJUDA_TIPOS = ['quebrado', 'noivo', 'carona', 'festa'];
const MissaoAjuda = { t: 0 };
MissaoAjuda.update = function (dt) {
  const h = Profile.hist;
  if (!h || h.fim || h.cap !== 3 || Apresenta.on || !player || Game.mode !== 'play') return;
  const E = Events.cur;
  if (E) {
    // terminou: limpa logo para o próximo pedido começar (sem esperar o sorteio da cidade)
    if (E.over && E.endT > 8) {
      const ex = E.carX !== undefined ? E.carX : E.x, ey = E.carY !== undefined ? E.carY : E.y, v = Cam.view;
      const vis = v && ex > v.x0 - 120 && ex < v.x1 + 120 && ey > v.y0 - 120 && ey < v.y1 + 120;
      if (!vis || E.endT > 16) { Events.clear(); this.t = 3; }
    }
    return;
  }
  if (Events.busy() || Socorro.job) { this.t = Math.max(this.t, 2); return; }
  this.t -= dt; if (this.t > 0) return;
  const tipos = AJUDA_TIPOS.filter((t) => t !== Events.lastType).sort(() => Math.random() - 0.5);
  for (const t of tipos) if (Events.spawn(t)) { Events.lastType = t; Events.cur.missao = true; break; }
  this.t = Events.cur ? 0 : 5;
  if (Events.cur) {
    const C = Events.cur, x = C.pick ? C.pick.x : C.x, y = C.pick ? C.pick.y : C.y;
    Nevoa.revela(x, y, 500);
    Missao.legenda('<b>' + escapeHtml(EV_NAMES[C.type]) + '</b>: aperte <b>Y</b> para ajudar.', 6);
  }
};

/* ---------- capítulo 6: o Juninho e o Opalha parado (chupeta na bateria) ---------- */
const MissaoOpalha = { t: 0 };
MissaoOpalha.nasce = function () {
  if (!player) return false;
  if (Events.cur && !Events.cur.over && Events.cur.opalha) return true;
  if (Events.cur) Events.clear(); // tira evento comum que estivesse na tela
  let E = null;
  for (let i = 0; i < 6 && !E; i++) E = evMakeQuebrado();
  if (!E) return false;
  E.model = 'muscle'; E.color = '#141416'; E.kind = 'bateria'; E.smoke = 0; E.who = 'Juninho';
  E.type = 'quebrado'; E.t = 0; E.stage = 'wait'; E.life = 1e9; E.opalha = true; E.missao = true;
  E.id = Events.idc = (Events.idc || 0) + 1;
  E.intro = 'O Juninho está com o Opalha parado. Siga o ponto rosa no mapa.';
  Events.cur = E; Act.gpsT = 0;
  Nevoa.revela(E.x, E.y, 500);
  return true;
};
MissaoOpalha.update = function (dt) {
  const h = Profile.hist;
  if (!h || h.fim || h.cap !== 5 || Apresenta.on || !player || Game.mode !== 'play') return;
  const E = Events.cur;
  if (E && E.opalha) {
    if (E.over && E.ok && !h.juninho) {
      h.juninho = true; saveGame();
      const m = charVoice('juninho_empresta');
      if (m && m.voice) setTimeout(() => VoicePlayer.play(m), 1200);
      Missao.legenda('<b>Juninho</b>: "Valeu, parceiro! Na hora do racha, o Opalha é teu."', 7);
    }
    return;
  }
  if (h.juninho) return;
  if (E && !E.over) return; // espera o evento comum acabar
  if (Events.busy() || Socorro.job) return;
  this.t -= dt; if (this.t > 0) return; this.t = 4;
  MissaoOpalha.nasce();
};

/* ---------- capítulo 7: o Opalha emprestado para o racha ---------- */
const Emprestimo = {};
Emprestimo.empresta = function () {
  if (Profile.owned[SONHO] || Profile.emprestimo) return;
  Profile.emprestimo = { prev: Profile.current, tinha: !!(Profile.cars && Profile.cars[SONHO]) };
  const cfg = carCfg(SONHO); cfg.color = '#141416';
  if (Profile.current !== SONHO) { stashCondition(Profile.current); Profile.current = SONHO; loadCondition(SONHO); Som.on = false; }
  if (player) player.setCar(SONHO);
  Profile.damage = 0; Profile.fuel = 100;
  toast('Opalha emprestado', 'O Juninho te emprestou o Opalha 6C para o racha. Cuida bem!', 'good');
  saveGame();
};
Emprestimo.devolve = function (calado) {
  const E = Profile.emprestimo; if (!E) return;
  Profile.emprestimo = null;
  if (Profile.owned[SONHO]) return;
  const volta = Profile.owned[E.prev] ? E.prev : Object.keys(Profile.owned)[0];
  if (Profile.current === SONHO) { stashCondition(SONHO); Profile.current = volta; loadCondition(volta); Som.on = false; if (player) player.setCar(volta); }
  if (!E.tinha && Profile.cars) delete Profile.cars[SONHO];
  if (!calado) setTimeout(() => toast('Opalha devolvido', 'O Juninho buscou o Opalha. Agora é juntar o dinheiro pra ter o seu.', 'info'), 5000);
  saveGame();
};
/* ============================ ÁGUA VIVA E CHÃO MOLHADO ============================
   Desenhado por cima do chão pré-renderizado, só no que está na tela:
   - rio: correnteza em duas camadas (fina e larga), ondinhas em "V" descendo, redemoinhos nas margens,
     folhas e galhinhos boiando, espuma logo depois das pontes e brilho da lua;
   - praia: a onda chega (crista), quebra, sobe espumando na areia, volta e deixa a areia molhada secando;
   - chuva: só o asfalto um pouco mais escuro e a terra virando barro (sem respingos nem riscos). */
const Agua = { pontes: null };
Agua.prepara = function () {
  this.pontes = World.edges.filter((e) => e.bridge).map((e) => ({ y0: e.a.y - e.hw - 16, y1: e.a.y + e.hw + 16, x0: e.bridge.x0, x1: e.bridge.x1 }));
  // trechos da beira do mar que são água de verdade (o píer e o porto ficam de fora) e onde a água começa em cada ponto
  this.trechos = []; this.beira = new Float32Array(Math.ceil(WORLD_W / 20) + 2);
  let ini = null;
  for (let x = 0, i = 0; x <= WORLD_W; x += 20, i++) {
    let y = SEA_Y - 10; while (y < SEA_Y + 60 && groundAt(x, y) !== SF.WATER) y += 4;
    this.beira[i] = y;
    const ok = y < SEA_Y + 60 && groundAt(x, y + 50) === SF.WATER;
    if (ok && ini === null) ini = x;
    if ((!ok || x >= WORLD_W) && ini !== null) { if (x - ini > 40) this.trechos.push([ini, x - 20]); ini = null; }
  }
};
const _sob = (P, x, y) => { for (const p of P) if (y > p.y0 && y < p.y1 && x > p.x0 - 20 && x < p.x1 + 20) return true; return false; };

// ---------- rio ----------
// tudo preso ao mapa (nada depende de onde a câmera está): parar o carro não muda nada na água
Agua.rio = function (ctx, view) {
  const ya = Math.max(view.y0 - 40, 0), yb = Math.min(view.y1 + 40, SEA_Y);
  if (yb <= ya) return;
  const cxm = riverCX((ya + yb) / 2);
  if (cxm + 260 < view.x0 || cxm - 260 > view.x1) return;
  const T = Game.time, P = this.pontes || [];
  const fl = 20 + Weather.rain * 14; // velocidade da correnteza (a chuva engrossa)
  const X = (y, f) => riverCX(y) + f * riverHW(y); // f de -1 (margem esquerda) a 1 (direita)
  // percorre as marcas de uma faixa que desce com a correnteza: cada marca tem número fixo (n) e sorteio próprio
  const faixa = (passo, vel, sem, fn) => {
    const off = ((T * vel + sem * passo) % passo + passo) % passo;
    for (let n = Math.floor((ya - off) / passo) - 1, y; (y = n * passo + off) < yb; n++) {
      if (y < ya - 60 || _sob(P, cxm, y)) continue;
      fn(y, n);
    }
  };
  ctx.save(); ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  // 1) o corpo da água: veios largos e macios, mais lentos perto da margem
  ctx.lineWidth = 9; ctx.strokeStyle = 'rgba(130,180,210,0.06)';
  ctx.beginPath();
  for (let k = -3; k <= 3; k++) {
    const vel = fl * 0.65 * (1.15 - Math.abs(k) / 6);
    faixa(170, vel, hash2(k + 30, 7), (y, n) => {
      const f = k / 3.8 + (hash2(n, k + 40) - 0.5) * 0.12, L = 60 + hash2(n, k + 3) * 50, s = (hash2(n, k + 5) - 0.5) * 10;
      ctx.moveTo(X(y, f), y); ctx.quadraticCurveTo(X(y + L / 2, f) + s, y + L / 2, X(y + L, f), y + L);
    });
  }
  ctx.stroke();
  // 2) riscos finos de correnteza, curvinhos, em dois tons (uns mais fortes, outros quase sumindo)
  ctx.lineWidth = 1.2;
  for (const [cor, par] of [['rgba(215,235,246,0.10)', 0], ['rgba(225,242,250,0.22)', 1]]) {
    ctx.strokeStyle = cor; ctx.beginPath();
    for (let k = -5; k <= 5; k++) {
      const vel = fl * (1.3 - Math.abs(k) / 7), passo = 70 + (k & 1) * 26;
      faixa(passo, vel, hash2(k + 9, 3), (y, n) => {
        if (((n + k) & 1) !== par) return;
        const f = k / 5.8 + (hash2(n, k + 21) - 0.5) * 0.1, L = 12 + hash2(n, k) * 20, s = (hash2(n, k + 22) - 0.5) * 4;
        ctx.moveTo(X(y, f), y); ctx.quadraticCurveTo(X(y + L / 2, f) + s, y + L / 2, X(y + L, f), y + L);
      });
    }
    ctx.stroke();
  }
  // 3) ondinhas em "V" descendo atrás de pedrinhas (abrem e fecham devagar)
  ctx.strokeStyle = 'rgba(228,242,250,0.2)'; ctx.lineWidth = 1;
  ctx.beginPath();
  for (let i = 0; i < 12; i++) {
    faixa(320, fl * 0.85, hash2(i, 52), (y, n) => {
      const f = (hash2(n, i + 51) - 0.5) * 1.3, x = X(y, f), w = 4 + hash2(n, i + 53) * 4 + Math.sin(T * 1.3 + n + i) * 1.2;
      ctx.moveTo(x - w, y - w * 0.8); ctx.quadraticCurveTo(x - w * 0.3, y - w * 0.1, x, y); ctx.quadraticCurveTo(x + w * 0.3, y - w * 0.1, x + w, y - w * 0.8);
    });
  }
  ctx.stroke();
  // 4) redemoinhos fixos no mapa, perto das margens, girando
  ctx.strokeStyle = 'rgba(215,235,245,0.2)'; ctx.lineWidth = 1;
  ctx.beginPath();
  const PR = 230;
  for (let c = Math.floor(ya / PR); c * PR < yb; c++) {
    if (hash2(c, 60) < 0.35) continue;
    const y = c * PR + hash2(c, 61) * PR; if (y < ya || y > yb || _sob(P, cxm, y)) continue;
    const sd = hash2(c, 65) < 0.5 ? 1 : -1, x = X(y, sd * (0.72 + hash2(c, 62) * 0.14)), r = 5 + hash2(c, 63) * 4, a0 = T * (1.1 + hash2(c, 64) * 0.6) * sd;
    ctx.moveTo(x + Math.cos(a0) * r, y + Math.sin(a0) * r * 0.75); ctx.ellipse(x, y, r, r * 0.75, 0, a0, a0 + 3.6);
    const a1 = a0 + 2.4; ctx.moveTo(x + Math.cos(a1) * r * 0.45, y + Math.sin(a1) * r * 0.34); ctx.ellipse(x, y, r * 0.45, r * 0.34, 0, a1, a1 + 3.2);
  }
  ctx.stroke();
  // 5) marolinha batendo nas margens (linha macia que respira)
  ctx.strokeStyle = 'rgba(225,240,248,0.26)'; ctx.lineWidth = 1.2;
  ctx.beginPath();
  for (const sd of [-1, 1]) {
    let first = true;
    for (let y = Math.floor(ya / 8) * 8; y <= yb; y += 8) {
      if (_sob(P, cxm, y)) { first = true; continue; }
      const x = riverCX(y) + sd * (riverHW(y) - 4 - (1 + Math.sin(y * 0.07 - T * 1.8 + sd)) * 2);
      if (first) { ctx.moveTo(x, y); first = false; } else ctx.lineTo(x, y);
    }
  }
  ctx.stroke();
  // 6) espuma logo depois das pontes (a água bate nos pilares)
  ctx.fillStyle = 'rgba(235,245,250,0.32)';
  for (const p of P) {
    const y = p.y1 - 10; if (y < ya || y > yb + 60) continue;
    for (let j = 0; j < 9; j++) {
      const f = -0.8 + j * 0.2, yy = y + ((T * fl * 0.6 + j * 13) % 46);
      ctx.globalAlpha = 1 - ((yy - y) / 46); ctx.beginPath(); ctx.ellipse(X(yy, f), yy, 3.5, 1.6, 0, 0, TAU); ctx.fill();
    }
    ctx.globalAlpha = 1;
  }
  // 7) folhas e galhinhos boiando, descendo devagar e balançando
  for (let i = 0; i < 10; i++) {
    faixa(1100, fl * 0.5, hash2(i, 72), (y, n) => {
      const f = (hash2(n, i + 71) - 0.5) * 1.4, x = X(y, f) + Math.sin(T * 0.7 + i + n) * 3, a = T * 0.25 + i + n;
      ctx.save(); ctx.translate(x, y); ctx.rotate(a);
      ctx.fillStyle = (i + n) % 3 ? 'rgba(70,90,40,0.85)' : 'rgba(92,64,38,0.85)';
      if ((i + n) % 3) { ctx.beginPath(); ctx.ellipse(0, 0, 2.6, 1.2, 0, 0, TAU); ctx.fill(); } else ctx.fillRect(-4, -0.6, 8, 1.2);
      ctx.restore();
    });
  }
  // 8) brilho da lua piscando, preso ao mapa e descendo junto com a água
  ctx.fillStyle = 'rgb(235,245,255)';
  for (let i = 0; i < 6; i++) {
    faixa(140, fl * 0.8, hash2(i, 77), (y, n) => {
      const ph = (T * 0.7 + hash2(n, i + 5) * 9) % 3; if (ph > 0.9) return;
      const x = X(y, (hash2(n, i + 13) - 0.5) * 1.5), a = Math.sin(ph / 0.9 * Math.PI);
      ctx.globalAlpha = a * 0.55; ctx.fillRect(x - 3, y - 0.6, 6, 1.2); ctx.fillRect(x - 1.2, y + 1.6, 2.4, 1);
    });
  }
  ctx.restore();
};

// ---------- praia: ciclo da onda ----------
// cada trecho da praia tem a sua fase: a onda vem (crista), quebra, sobe na areia espumando, volta e a areia fica molhada secando
Agua.mar = function (ctx, view, topo) {
  if (view.y1 < SAND_Y - 20 || !this.trechos) return;
  const T = Game.time, B = this.beira;
  const by = (x) => { const f = x / 20, i = Math.floor(f), t = f - i; return lerp(B[i] || SEA_Y, B[i + 1] || SEA_Y, t); };
  const praia = (x) => x >= ORLA_X0 + 40; // na Serra o mar bate na mata/pedra: espuma sem subir na areia
  const PER = 8; // segundos por onda
  const fase = (x) => ((T / PER + Math.sin(x * 0.0021) * 0.35 + Math.sin(x * 0.0007 + 1.3) * 0.2) % 1 + 1) % 1;
  const corre = (x) => (praia(x) ? 26 + Math.sin(x * 0.013) * 6 : 4); // quanto a onda sobe na areia
  // posição da frente da água em relação à beira (negativo = subiu na areia)
  const frente = (x) => {
    const p = fase(x), R = corre(x);
    if (p < 0.55) return 0;
    if (p < 0.72) { const u = (p - 0.55) / 0.17; return -R * Math.sin(u * Math.PI / 2); }
    const u = (p - 0.72) / 0.28; return -R * (1 - u * u * (3 - 2 * u));
  };
  ctx.save(); ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  for (const [a0, a1] of this.trechos) {
    const x0 = Math.max(a0, view.x0 - 20), x1 = Math.min(a1, view.x1 + 20);
    if (x1 <= x0) continue;
    const xs = []; for (let x = x0; x <= x1; x += 12) xs.push(x); if (xs[xs.length - 1] < x1) xs.push(x1);
    if (!topo) {
      // areia molhada: escura onde a onda acabou de passar, secando aos poucos
      ctx.fillStyle = 'rgba(38,48,54,0.28)';
      ctx.beginPath(); ctx.moveTo(xs[0], by(xs[0]) + 2);
      for (const x of xs) { const p = fase(x), seca = p > 0.72 ? 1 - (p - 0.72) / 0.28 * 0.5 : p < 0.55 ? 0.5 - p / 0.55 * 0.3 : 1; ctx.lineTo(x, by(x) - corre(x) * Math.max(0.2, seca) - 2); }
      for (let i = xs.length - 1; i >= 0; i--) ctx.lineTo(xs[i], by(xs[i]) + 2);
      ctx.closePath(); ctx.fill();
      // brilho molhado na areia logo atrás da água
      ctx.fillStyle = 'rgba(170,190,205,0.12)';
      ctx.beginPath(); ctx.moveTo(xs[0], by(xs[0]));
      for (const x of xs) ctx.lineTo(x, by(x) + frente(x) - 5);
      for (let i = xs.length - 1; i >= 0; i--) ctx.lineTo(xs[i], by(xs[i]) + frente(xs[i]));
      ctx.closePath(); ctx.fill();
    }
    // cristas chegando (antes de quebrar): linha clara ficando mais grossa perto da beira
    for (let w = 0; w < 3; w++) {
      ctx.beginPath(); let caneta = false, pp = -1;
      for (const x of xs) {
        const p = (fase(x) + w / 3) % 1;
        // levanta a caneta onde a onda já quebrou ou onde a fase virou (sem riscos retos ligando pontos longe)
        if (p > 0.55 || (pp >= 0 && Math.abs(p - pp) > 0.2)) { caneta = false; pp = p; if (p > 0.55) continue; }
        pp = p;
        const u = p / 0.55, y = by(x) + 120 * (1 - u) + 4 + Math.sin(x * 0.04 + T) * 1.5;
        if (caneta) ctx.lineTo(x, y); else { ctx.moveTo(x, y); caneta = true; }
      }
      ctx.strokeStyle = 'rgba(232,244,250,0.32)'; ctx.lineWidth = 1.2 + w * 0.4; ctx.stroke();
    }
    // água subindo na areia (lâmina clara) com a espuma na ponta
    ctx.fillStyle = 'rgba(200,225,235,0.22)';
    ctx.beginPath(); ctx.moveTo(xs[0], by(xs[0]) + 6);
    for (const x of xs) ctx.lineTo(x, by(x) + frente(x));
    for (let i = xs.length - 1; i >= 0; i--) ctx.lineTo(xs[i], by(xs[i]) + 6);
    ctx.closePath(); ctx.fill();
    // espuma: faixa branca na ponta da água (mais grossa quando a onda acabou de quebrar)
    ctx.fillStyle = 'rgba(246,251,253,0.7)';
    ctx.beginPath();
    xs.forEach((x, i) => { const y = by(x) + frente(x) + Math.sin(x * 0.09 + T * 1.6) * 1.2; i ? ctx.lineTo(x, y) : ctx.moveTo(x, y); });
    for (let i = xs.length - 1; i >= 0; i--) {
      const x = xs[i], p = fase(x), g = p > 0.55 && p < 0.8 ? 5.5 : 2.6;
      ctx.lineTo(x, by(x) + frente(x) + g + Math.sin(x * 0.05 - T) * 1.4);
    }
    ctx.closePath(); ctx.fill();
    // linha de espuma que fica onde a onda chegou mais alto, sumindo devagar
    ctx.strokeStyle = 'rgba(240,248,252,0.35)'; ctx.lineWidth = 1;
    ctx.beginPath();
    xs.forEach((x, i) => { const p = fase(x); const y = by(x) - corre(x) + 1; if (p < 0.72 || !praia(x)) { ctx.moveTo(x, y); return; } ctx.lineTo(x, y); });
    ctx.stroke();
    // bolhinhas da espuma
    ctx.fillStyle = 'rgba(255,255,255,0.55)';
    for (let x = Math.ceil(x0 / 7) * 7; x <= x1; x += 7) {
      const h = hash2(x, 41); if (h > 0.5) continue;
      ctx.fillRect(x, by(x) + frente(x) + 3 + h * 12 + Math.sin(T * 2 + x) * 1.2, 1.3, 1.3);
    }
  }
  ctx.restore();
};

// ---------- chão molhado (só escurece; sem respingos nem riscos) ----------
Agua.molhado = function (ctx, view) {
  const w = Weather.wet; if (w < 0.04) return;
  ctx.save();
  ctx.fillStyle = `rgba(4,10,22,${(0.2 * w).toFixed(3)})`;
  ctx.beginPath();
  const vis = [];
  for (const e of World.edges) {
    const r = e.h ? [Math.min(e.a.x, e.b.x), e.a.y - e.hw, Math.max(e.a.x, e.b.x), e.a.y + e.hw] : [e.a.x - e.hw, Math.min(e.a.y, e.b.y), e.a.x + e.hw, Math.max(e.a.y, e.b.y)];
    if (r[2] < view.x0 || r[0] > view.x1 || r[3] < view.y0 || r[1] > view.y1) continue;
    vis.push([e, r]);
    if (e.T.asphalt && !e.bridge) ctx.rect(r[0], r[1], r[2] - r[0], r[3] - r[1]);
  }
  const nos = [];
  for (const n of World.nodes) {
    if (n.x + n.hx < view.x0 || n.x - n.hx > view.x1 || n.y + n.hy < view.y0 || n.y - n.hy > view.y1 || !n.hx) continue;
    const asf = n.edges.some((e) => e.T.asphalt); nos.push([n, asf]);
    if (asf) ctx.rect(n.x - n.hx, n.y - n.hy, n.hx * 2, n.hy * 2);
  }
  ctx.fill();
  ctx.fillStyle = `rgba(34,18,6,${(0.32 * w).toFixed(3)})`;
  ctx.beginPath();
  for (const [e, r] of vis) if (!e.T.asphalt) ctx.rect(r[0], r[1], r[2] - r[0], r[3] - r[1]);
  for (const [n, asf] of nos) if (!asf) ctx.rect(n.x - n.hx, n.y - n.hy, n.hx * 2, n.hy * 2);
  ctx.fill();
  ctx.restore();
};
// sem respingos no teto dos carros nem espirro do trânsito (o dono não gostou): ficam vazias
Agua.atualiza = function () {};
Agua.respingosCarro = function () {};

Agua.desenhaChao = function (ctx, view) {
  if (!this.pontes) this.prepara();
  if (Settings.quality !== 'baixa') { this.rio(ctx, view); this.mar(ctx, view); }
  this.molhado(ctx, view);
};

// por cima da escuridão: a espuma e o brilho da água aparecem de noite como se a lua batesse
Agua.luar = function (ctx, view) {
  if (Settings.quality === 'baixa' || !this.pontes) return;
  ctx.save(); ctx.globalAlpha = 0.55 * clamp(Cam.dark || 0.7, 0.3, 1);
  this.rio(ctx, view); this.mar(ctx, view, true);
  ctx.restore();
};
/* ============================ JOGO / LOOP PRINCIPAL ============================ */
const Game = {
  mode: 'menu', time: 0, autosaveT: 30, fpsT: 0, fpsN: 0,
  get state() { return this.mode === 'menu' ? 'menu' : (Screens.current && Screens.current !== 'screen-phone' ? 'paused' : 'playing'); }, // celular aberto não pausa
};
const NIGHT_START = 19 * 60 + 30, NIGHT_END = 29 * 60;

function startPlay() {
  AudioSys.init();
  Act.reset(); Events.reset(); CarLife.reset(); Som.on = false; Radio.stop(); Settings.radioOff = true; if (typeof saveSettings === "function") saveSettings(); // a rádio sempre começa desligada (liga no F)
  player = new Player(Profile.current);
  let pos = World.home;
  const sp = Profile.pos;
  if (sp && isFinite(sp.x) && isFinite(sp.y) && sp.x > 60 && sp.y > 60 && sp.x < WORLD_W - 60 && sp.y < WORLD_H - 60 && groundAt(sp.x, sp.y) !== SF.WATER) pos = sp;
  player.place(pos.x, pos.y, pos.a || 0);
  if (player.collide() > 0 || player.inWater()) { player.place(World.home.x, World.home.y, 0); }
  Game.mode = 'play';
  Screens.closeAll();
  Cam.x = player.x; Cam.y = player.y; Cam.zoom = screenZoomBase() * Settings.zoom / 100;
  forceGround = true;
  Traffic.fill(player.x, player.y);
  UI.region = null; UI.last = {};
  Game.autosaveT = 30;
  updateHudVisibility();
  Nevoa.carrega(); Historia.h(); if (Apresenta.on) Apresenta.encerra();
  Profile.welcomed = true; // sem áudio de boas-vindas (o tutorial do Seu Zé já fala)
}
// tela de carregamento entre o menu e o jogo, com dica
function withTransit(fn) {
  const el = $('transit'), fill = $('transit-fill'), txt = $('transit-text');
  if (!el) { fn(); return; }
  // na versão do navegador não tem a tela de carregar entre o menu e o jogo (o app do Windows continua com ela);
  // os testes automáticos continuam usando a tela (navigator.webdriver)
  const desktop = !!(window.brnd && window.brnd.desktop);
  if (!desktop && !navigator.webdriver) { Game.carregando = false; Game.posCarga = 0; fn(); return; }
  const MSG = ['Procurando a chave…', 'Ligando o motor…', 'Esquentando o óleo…', 'Ajustando o retrovisor…', 'Acordando a cidade…', 'Acendendo os postes…', 'Chamando o trânsito…', 'Bora rodar!'];
  // 3 dicas diferentes, uma a cada 2 segundos
  const tips = LOAD_TIPS.slice().sort(() => Math.random() - 0.5).slice(0, 3), tipEl = $('transit-tip');
  let tipI = 0; tipEl.innerHTML = '<b>DICA</b>' + tips[0]; tipEl.style.opacity = 1;
  txt.textContent = MSG[0]; fill.style.width = '0%';
  el.classList.remove('hidden', 'fade');
  Game.carregando = true; Game.posCarga = 0; // nada fala nem reage antes do fim do carregamento
  const t0 = performance.now(), D = 6600;
  setTimeout(fn, 40); // monta o jogo por trás da tela de carregamento
  const step = (now) => {
    const k = Math.min(1, (now - t0) / D);
    fill.style.width = (k * 100).toFixed(1) + '%';
    txt.textContent = MSG[Math.min(MSG.length - 1, Math.floor(k * MSG.length))];
    const ti = Math.min(tips.length - 1, Math.floor((now - t0) / 2200));
    if (ti !== tipI) { tipI = ti; tipEl.style.opacity = 0; setTimeout(() => { tipEl.innerHTML = '<b>DICA</b>' + tips[ti]; tipEl.style.opacity = 1; }, 220); }
    if (k < 1) requestAnimationFrame(step);
    else { el.classList.add('fade'); setTimeout(() => { el.classList.add('hidden'); Game.carregando = false; }, 460); }
  };
  requestAnimationFrame(step);
}
function newGame() { withTransit(newGameNow); }
// carro e teclas travados: carregando, câmera apresentando lugares, ou primeira noite antes da apresentação começar
function jogoTravado() {
  if (Game.carregando || Apresenta.on) return true;
  if (navigator.webdriver && !window.__intro) return false; // testes antigos: sem apresentação, sem espera
  const h = Profile.hist; return !!(h && h.cap === 0 && !h.apres && !h.tudo);
}
// coisas que só acontecem depois que a tela de carregamento some (falas, avisos, tutorial)
const AposCarga = { fila: [] };
function aposCarregar(fn, s) { AposCarga.fila.push({ fn, s: s || 0 }); }
function carregou(seg) { return !Game.carregando && (Game.posCarga === undefined || Game.posCarga >= (seg || 0)); }
AposCarga.update = function (dt) {
  if (Game.carregando) return;
  if (Game.posCarga !== undefined) Game.posCarga += dt;
  const pc = Game.posCarga === undefined ? 1e9 : Game.posCarga;
  for (let i = this.fila.length - 1; i >= 0; i--) { const q = this.fila[i]; if (pc >= q.s) { this.fila.splice(i, 1); try { q.fn(); } catch (e) { console.error(e); } } }
};
function newGameNow() {
  Profile = newProfile();
  startPlay();
  saveGame();
  // as boas-vindas agora são a apresentação da cidade (câmera de cinema) no começo da história
  Profile.tut = 0; Tutorial.t = 0; Tutorial.d0 = Profile.distance || 0; Tutorial.shown = -1; Tutorial.rapido = false;
}
function continueGame() {
  const p = loadProfileFromStorage();
  if (!p) { AudioSys.error(); return; }
  withTransit(() => continueGameNow(p));
}
function continueGameNow(p) {
  Profile = p;
  startPlay();
  aposCarregar(() => toast('Bem-vindo de volta', 'R$ ' + fmtMoney(Profile.money) + ' na carteira · ' + carById(Profile.current).name, 'info'), 0.6);
}
function saveGame() {
  if (player && Game.mode === 'play') Profile.pos = { x: player.x, y: player.y, a: player.a };
  writeProfile();
}
function toMenu() {
  Game.mode = 'menu';
  player = null;
  Act.reset(); Events.reset(); CarLife.reset(); Som.on = false; Radio.stop();
  Screens.closeAll();
  Screens.open('screen-main');
  AudioSys.hornOn = false;
}
function resetVehicle() {
  if (!player) return;
  const ne = nearestEdge(player.x, player.y);
  const e = ne.e;
  const s = clamp(ne.s, e.clearA + 10, Math.max(e.clearA + 10, e.len - e.clearB - 10));
  const off = e.T.lanes[e.T.lanes.length - 1];
  const x = e.a.x + e.dx * s - e.dy * off, y = e.a.y + e.dy * s + e.dx * off;
  player.place(x, y, Math.atan2(e.dy, e.dx));
  Cam.x = x; Cam.y = y;
  toast('Veículo reposicionado', 'Você está na ' + e.name + '.', 'info');
}
function onWindowBlur() { if (Game.state === 'playing') Screens.open('screen-pause'); }
document.addEventListener('visibilitychange', () => { if (document.hidden) onWindowBlur(); });
window.addEventListener('beforeunload', () => { if (Game.mode === 'play') saveGame(); });

function handleKeys() {
  while (KeyPress.length) {
    const k = KeyPress.shift();
    if (Apresenta.on && (k === 'Escape' || k === 'Enter' || k === 'Space' || k === 'NumpadEnter')) { Apresenta.pula(); continue; }
    if (jogoTravado() && k !== 'Escape') continue; // nada funciona durante a apresentação
    if (k === 'Escape') {
      if (Game.mode === 'play' && !Screens.current) { Screens.open('screen-pause'); AudioSys.click(); }
      else if (Screens.current && Screens.current !== 'screen-main') Screens.back();
      continue;
    }
    // Q: abre o celular; apertando de novo guarda o celular e fecha o que estiver aberto (inclusive o mapa)
    if (k === 'KeyQ' && Game.mode === 'play' && (Screens.current === 'screen-phone' || Screens.current === 'screen-map')) { Screens.closeAll(); AudioSys.tone(900, 0.05, 'sine', 0.05, 'ui', 600); continue; }
    if (Game.state !== 'playing') continue;
    switch (k) {
      case 'KeyE': if (Act.prompt) Act.prompt.act(); break;
      case 'KeyY': Events.answerOffer(true); break;
      case 'KeyN': Events.answerOffer(false); break;
      case 'KeyQ': Phone.open('home'); break;
      case 'KeyH': player.lightsOff = !player.lightsOff; AudioSys.tone(player.lightsOff ? 600 : 900, 0.05, 'square', 0.05, 'ui'); toast(player.lightsOff ? 'Farol desligado' : 'Farol ligado', '', 'info'); break;
      case 'KeyB': Som.toggle(); break;
      case 'KeyF': Radio.toggle(); break;
      case 'KeyL': player.highBeam = !player.highBeam; AudioSys.tone(900, 0.04, 'square', 0.05, 'ui'); break;
      case 'KeyC': { // troca a altura da câmera: 1 → 2 → 3 → 1
        Settings.cam = String(Settings.cam % 3 + 1); Settings.zoom = CAM_LEVELS[Settings.cam]; saveSettings(); syncSettingsUI();
        AudioSys.tone(900, 0.04, 'square', 0.05, 'ui'); toast('Câmera: nível ' + Settings.cam, Settings.cam === '1' ? 'Mais perto do carro.' : Settings.cam === '3' ? 'Mais alto, vê mais a cidade.' : 'Altura do meio.', 'info'); break;
      }
      case 'KeyR': if (player.speed < 120) resetVehicle(); break;
    }
  }
}
function stepPlay(dt) {
  Game.time += dt;
  Profile.time += dt;
  if (Profile.time >= NIGHT_END) { Profile.nights = (Profile.nights || 0) + 1; Profile.time = NIGHT_START; toast('Uma nova noite começa', 'O relógio volta para as 19:30. A cidade nunca dorme.', 'info'); Finance.newDay(); }
  const locked = Act.race && Act.race.count > 0;
  // começo do jogo e cenas de apresentação: carro desligado e parado (nada de tecla; antes o "freio" virava ré e o carro sumia)
  const trava = jogoTravado();
  const inp = trava ? { thr: false, brk: false, steer: 0, hb: false } : { thr: !locked && !!key.up(), brk: !!key.down(), steer: (key.right() ? 1 : 0) - (key.left() ? 1 : 0), hb: !!key.hb() };
  if (trava) { player.vx = player.vy = 0; if (player.spin) player.spin = 0; }
  player.update(dt, inp);
  if (trava) { player.vx = player.vy = 0; }
  Traffic.update(dt, Game.time, player.x, player.y, Cam.view);
  Animals.update(dt, Cam.x, Cam.y);
  if (Settings.quality !== 'baixa') Peladas.update(dt, Cam.x, Cam.y);
  Particles.update(dt);
  updateActivities(dt);
  Events.update(dt);
  MissaoAjuda.update(dt); MissaoOpalha.update(dt); Nevoa.update(dt);
  CarLife.update(dt);
  Finance.update(dt);
  Som.update(dt);
  Socorro.update(dt);
  Achievements.check(dt);
  Historia.update(dt);
  Weather.updatePlayer(dt, player);
  Police.update(dt);
  if (CHEATS_ENABLED && Cheats.god && (Profile.damage > 0 || (Profile.zones && (Profile.zones.f || Profile.zones.r || Profile.zones.l || Profile.zones.rt)))) { Profile.damage = 0; Profile.zones = { f: 0, r: 0, l: 0, rt: 0, seed: ((Profile.zones && Profile.zones.seed) || 0) + 1 }; }
  const kmh = player.speed * 0.3; if (kmh > (Profile.topSpeed || 0)) Profile.topSpeed = kmh;
  if (player.drift > 0.45 && player.speed > 180) Profile.driftT = (Profile.driftT || 0) + dt;
}
function stepMenu(dt) {
  Game.time += dt;
  Traffic.update(dt, Game.time, Cam.x, Cam.y, Cam.view);
  Animals.update(dt, Cam.x, Cam.y);
  if (Settings.quality !== 'baixa') Peladas.update(dt, Cam.x, Cam.y);
  Particles.update(dt);
}
const STEP = 1 / 120;
let lastT = 0, accT = 0;
let fpsGate = 0;
function frame(now) {
  requestAnimationFrame(frame);
  // trava de FPS (30, 60 ou 120): pula o quadro que chegou antes da hora, sem mexer na física (ela usa o tempo real)
  const cap = +Settings.fpsCap || 0;
  if (cap) {
    const iv = 1000 / cap;
    if (now < fpsGate - 1) return;
    fpsGate = now - fpsGate > iv ? now + iv : fpsGate + iv;
  }
  const t0q = performance.now();
  let dt = lastT ? (now - lastT) / 1000 : 0.016;
  if (lastT && Game.state === 'playing') AutoRes.quadro(dt, frame.trab || 0, cap);
  lastT = now;
  dt = clamp(dt, 0, 0.1);
  handleKeys();
  const st = Game.state;
  if (st === 'playing' || st === 'menu') {
    accT += dt;
    let n = 0;
    while (accT >= STEP && n < 12) { if (st === 'playing') { if (!Game.carregando) stepPlay(STEP); } else stepMenu(STEP); accT -= STEP; n++; }
    if (n >= 12) accT = 0;
    updateCamera(dt);
    Apresenta.update(dt); // viagem da câmera até os lugares da missão
    updateFireflies(dt);
    Weather.update(dt); Agua.atualiza(dt);
  } else accT = 0;
  // enquanto a tela de carregar está na frente: tudo mudo (volume geral a zero); volta quando ela some
  if (AudioSys.ctx && AudioSys.master && frame.mudo !== !!Game.carregando) {
    frame.mudo = !!Game.carregando;
    AudioSys.master.gain.setTargetAtTime(frame.mudo ? 0 : (Settings.master / 100) * 0.9, AudioSys.ctx.currentTime, 0.06);
  }
  AposCarga.update(dt);
  Radio.update(dt);
  if (!Game.carregando) { Ambiente.update(dt); PedVoz.update(); } // sons de ambiente por região; voz do pedestre
  Atropelo.update(dt); Colecao.update(dt); // voz do pedestre abaixando com a distância; atropelamento
  AudioSys.hornOn = Game.state === 'playing' && !!key.horn();
  render();
  updateHUD(dt);
  Tutorial.update(dt);
  CamPrev.update(dt);
  if (Screens.current === 'screen-garage') drawGaragePreview(dt);
  if (Screens.current === 'screen-map' && bigMap) bigMap.draw();
  else if (Screens.current === 'screen-phone' && phoneMap && Phone.app === 'mapa') phoneMap.draw();
  if (AudioSys.ok) {
    const R = REGIONS[regionKeyAt(Cam.x, Cam.y)];
    const river = Math.max(clamp(1 - (Math.abs(Cam.x - riverCX(Cam.y)) - 160) / 650, 0, 1), clamp(1 - (SEA_Y - Cam.y) / 700, 0, 1) * 1.3); // rio e mar
    const p = player;
    AudioSys.update({
      active: Game.state === 'playing' && !jogoTravado() && !!p, rpm: p ? p.rpm : 900, thr: p ? p.thr : 0, speed: p ? p.speed : 0, slip: p ? p.slip : 0,
      surfaceRough: p ? SURF[p.surface].rough : 0, paved: p ? (p.surface === SF.ROAD || p.surface === SF.PAVED || p.surface === SF.BRIDGE || p.surface === SF.SIDEWALK) : true, rural: R.rural, city: R.city, river, pitch: p ? p.car.pitch : 1, cyl: p ? (p.car.cyl || 4) : 4,
    });
    let md = Infinity;
    for (const s of World.shops) if (s.kind === 'bar' || s.kind === 'lanchonete' || s.kind === 'churrascaria' || s.kind === 'fazenda') md = Math.min(md, Math.hypot(s.x - Cam.x, s.y - Cam.y));
    for (const q of World.parties) md = Math.min(md, Math.hypot(q.x - Cam.x, q.y - Cam.y) + (q.bar ? 60 : 0));
    AudioSys.music(Game.state === 'screen' ? 0 : Math.pow(clamp(1 - (md - 90) / 650, 0, 1), 1.6) * 0.32);
  }
  if (Game.state === 'playing') {
    Game.autosaveT -= dt;
    if (Game.autosaveT <= 0) { Game.autosaveT = 30; saveGame(); }
  }
  Game.fpsT += dt; Game.fpsN++;
  if (Game.fpsT >= 0.5) {
    if (Settings.showFps) {
      const f = Math.round(Game.fpsN / Game.fpsT), alvo = cap === 30 ? 30 : 60, el = $('fps');
      el.textContent = f + ' FPS';
      el.classList.toggle('medio', f < alvo * 0.92 && f >= alvo * 0.6); el.classList.toggle('ruim', f < alvo * 0.6);
    }
    Game.fpsT = 0; Game.fpsN = 0;
  }
  frame.trab = performance.now() - t0q; // tempo gasto neste quadro (para a nitidez automática)
}

async function boot() {
  const prog = (f, t) => { $('load-fill').style.width = Math.round(f * 100) + '%'; $('load-text').textContent = t; };
  const tick = () => new Promise((r) => requestAnimationFrame(() => r()));
  loadSettings();
  const saved = loadProfileFromStorage();
  if (saved) { Profile = saved; hasSave = true; }
  resize();
  bindMenus();
  bindSettings();
  $('garage-main-btn').addEventListener('click', () => Garage.main());
  document.querySelector('#screen-garage .garage-side').addEventListener('click', (e) => Garage.click(e));
  $('phone-body').addEventListener('click', (e) => Phone.click(e));
  $('phone-close').addEventListener('click', () => { AudioSys.back(); Screens.back(); });
  // botões de baixo do celular: bolinha volta para o início, seta volta para a tela de antes
  $('phone-nav-home').addEventListener('click', () => { if (Phone.app !== 'home') { phoneTone(1000, 0.04, 0.04); Phone.go('home'); } });
  $('phone-nav-back').addEventListener('click', () => {
    const b = [...document.querySelectorAll('#phone-body .ph-back, #phone-body [data-pgback], #phone-body [data-frback]')].find((x) => x.offsetParent !== null);
    if (b) b.click(); else if (Phone.app !== 'home') Phone.go('home');
  });
  // tocar nos botões do celular não rouba o teclado do carro (dá para dirigir com ele aberto)
  document.querySelector('#screen-phone .phone').addEventListener('mousedown', (e) => { if (e.target.closest('button')) e.preventDefault(); });
  $('hud-phone').addEventListener('click', () => { if (Game.state === 'playing' && !jogoTravado()) Phone.open('home'); });
  $('fps').classList.toggle('hidden', !Settings.showFps);
  prog(0.04, 'Preparando texturas…'); await tick();
  buildPatterns(); buildLightSprites();
  RNG = mulberry32(20261108);
  const steps = [
    [buildRoadGraph, 'Traçando ruas…'], [buildRiver, 'Enchendo o Rio Jururu…'], [buildRoadSurface, 'Asfaltando as avenidas…'],
    [buildCity, 'Erguendo bairros e comércios…'], [buildHighwayStrip, 'Abrindo a rodovia…'], [buildSerra, 'Subindo para Feio Rosa e Jardim Cara-Pintada…'], [buildRural, 'Plantando o interior…'], [buildLitoral, 'Molhando os pés na Orla de Camburiso…'],
    [buildRoadProps, 'Acendendo os postes…'], [buildActivitiesData, 'Espalhando segredos pela cidade…'],
  ];
  for (let i = 0; i < steps.length; i++) { prog(0.08 + i / steps.length * 0.72, steps[i][1]); await tick(); steps[i][0](); }
  alargaRuas(); empurraDaPista(); // ruas 10% mais largas (depois de montar tudo: a cidade não muda)
  pruneRoadTrees(); thinTrees(); addBuracos(); Colecao.monta();
  buildShadowSprites(); bakeLampShadows();
  prog(0.84, 'Desenhando o mapa…'); await tick();
  buildMapImage();
  Traffic.prepare();
  Animals.build();
  Peladas.build();
  RNG = mulberry32((Date.now() & 0xffffffff) >>> 0);
  Cam.x = 1756; Cam.y = 1500;
  Traffic.fill(Cam.x, Cam.y);
  prog(0.92, 'Ligando os faróis…'); await tick();
  Screens.open('screen-main');
  requestAnimationFrame(frame);
  await tick(); await tick();
  prog(0.97, 'Conferindo tudo…');
  await new Promise((r) => setTimeout(r, 500)); // meio segundo a mais para garantir que tudo assentou
  prog(1, 'Pronto.');
  $('loading').classList.add('fade');
  setTimeout(() => $('loading').remove(), 800);
  const unlock = () => { AudioSys.init(); };
  window.addEventListener('pointerdown', unlock, { once: true });
  window.addEventListener('keydown', unlock, { once: true });
}
boot().catch((err) => {
  console.error(err);
  const t = document.getElementById('load-text');
  if (t) t.textContent = 'Erro ao iniciar: ' + err.message;
});
